INSERT INTO questions (id, subject, topic, question_text, options, correct_answer_index, difficulty, explanation) VALUES
('cj_001', 'criminal_jurisprudence', 'Criminal Law Book I', 'What are the three main theories of criminal law?', '["Classical, Positivist, Eclectic", "Natural, Positive, Mixed", "Retributive, Deterrent, Rehabilitative", "Ancient, Modern, Contemporary"]'::jsonb, 0, 'easy', 'The three main theories are Classical (free will), Positivist (determinism), and Eclectic (combination of both).'),
('cj_002', 'criminal_jurisprudence', 'Criminal Law Book I', 'Under the Revised Penal Code, what is the age of absolute irresponsibility?', '["Below 15 years old", "Below 18 years old", "Below 12 years old", "Below 9 years old"]'::jsonb, 0, 'medium', 'Under RA 9344, a child below 15 years old is exempt from criminal liability (absolute irresponsibility).'),
('cj_003', 'criminal_jurisprudence', 'Justifying Circumstances', 'Which is NOT a justifying circumstance under Article 11 of the RPC?', '["Insanity", "Self-defense", "Defense of relatives", "Fulfillment of duty"]'::jsonb, 0, 'medium', 'Insanity is an exempting circumstance under Article 12, not a justifying circumstance.'),
('cj_004', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is the penalty for Murder under the Revised Penal Code?', '["Reclusion Perpetua to Death", "Reclusion Temporal", "Prision Mayor", "Life Imprisonment"]'::jsonb, 0, 'medium', 'Murder is punishable by Reclusion Perpetua to Death under Article 248 of the RPC.'),
('cj_005', 'criminal_jurisprudence', 'Criminal Procedure', 'What is the purpose of a preliminary investigation?', '["To determine probable cause", "To determine guilt", "To impose sentence", "To execute judgment"]'::jsonb, 0, 'easy', 'Preliminary investigation determines whether there is probable cause to charge a person with an offense.'),
('cj_006', 'criminal_jurisprudence', 'Rules of Evidence', 'What is the quantum of evidence required in criminal cases?', '["Proof beyond reasonable doubt", "Preponderance of evidence", "Substantial evidence", "Clear and convincing evidence"]'::jsonb, 0, 'easy', 'Criminal cases require proof beyond reasonable doubt to convict the accused.'),
('cj_007', 'criminal_jurisprudence', 'Exempting Circumstances', 'Which of the following is an exempting circumstance?', '["Minority", "Provocation", "Vindication of grave offense", "Voluntary surrender"]'::jsonb, 0, 'medium', 'Minority (below 15 years old) is an exempting circumstance under Article 12 of the RPC.'),
('cj_008', 'criminal_jurisprudence', 'Penalties and Punishment', 'What is the duration of Reclusion Perpetua?', '["20 years and 1 day to 40 years", "12 years and 1 day to 20 years", "6 years and 1 day to 12 years", "Life imprisonment"]'::jsonb, 0, 'hard', 'Reclusion Perpetua has a duration of 20 years and 1 day to 40 years.'),
('cj_009', 'criminal_jurisprudence', 'Mitigating Circumstances', 'Voluntary surrender is what kind of circumstance?', '["Mitigating", "Aggravating", "Exempting", "Justifying"]'::jsonb, 0, 'easy', 'Voluntary surrender is a mitigating circumstance that reduces the penalty.'),
('cj_010', 'criminal_jurisprudence', 'Court Testimony', 'What is the best evidence rule?', '["Original document must be presented", "Witness testimony is sufficient", "Copies are preferred", "Hearsay is admissible"]'::jsonb, 0, 'medium', 'The best evidence rule requires that the original document be presented when its contents are the subject of inquiry.'),
('cj_011', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is mala in se?', '["Acts wrong in themselves", "Acts wrong because prohibited by law", "Acts of negligence", "Acts of omission"]'::jsonb, 0, 'medium', 'Mala in se are acts that are inherently wrong or evil, such as murder, theft, and rape.'),
('cj_012', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is mala prohibita?', '["Acts wrong because prohibited by law", "Acts wrong in themselves", "Acts of self-defense", "Acts of passion"]'::jsonb, 0, 'medium', 'Mala prohibita are acts that are wrong only because they are prohibited by statute, like illegal parking.'),
('cj_013', 'criminal_jurisprudence', 'Criminal Law Book I', 'What are the elements of felony?', '["Act/Omission, Punishable by RPC, Done with deceit/fault", "Intent only", "Damage only", "Motive only"]'::jsonb, 0, 'hard', 'A felony requires: (1) an act or omission, (2) punishable by the RPC, and (3) done with deceit or fault.'),
('cj_014', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is dolo?', '["Deceit or malice", "Negligence", "Accident", "Self-defense"]'::jsonb, 0, 'medium', 'Dolo refers to deceit or malice - the deliberate intent to do an unlawful act.'),
('cj_015', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is culpa?', '["Fault or negligence", "Intentional act", "Premeditated act", "Conspiracy"]'::jsonb, 0, 'medium', 'Culpa refers to fault or negligence - lack of foresight or lack of skill.'),
('cj_016', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is aberratio ictus?', '["Mistake in the blow", "Mistake in identity", "Impossible crime", "Complex crime"]'::jsonb, 0, 'hard', 'Aberratio ictus is mistake in the blow - when the offender hits a different person due to lack of skill or poor aim.'),
('cj_017', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is error in personae?', '["Mistake in identity", "Mistake in the blow", "Praeter intentionem", "Complex crime"]'::jsonb, 0, 'hard', 'Error in personae is mistake in identity - when the offender kills a different person thinking they are someone else.'),
('cj_018', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is praeter intentionem?', '["Injury greater than intended", "Mistake in identity", "Mistake in the blow", "Self-defense"]'::jsonb, 0, 'hard', 'Praeter intentionem means the injury caused is greater than what was intended.'),
('cj_019', 'criminal_jurisprudence', 'Justifying Circumstances', 'What are the elements of self-defense?', '["Unlawful aggression, Reasonable necessity, Lack of provocation", "Only unlawful aggression", "Only reasonable force", "Only lack of provocation"]'::jsonb, 0, 'hard', 'Self-defense requires: (1) unlawful aggression, (2) reasonable necessity of means, and (3) lack of sufficient provocation.'),
('cj_020', 'criminal_jurisprudence', 'Justifying Circumstances', 'Which element is indispensable in self-defense?', '["Unlawful aggression", "Reasonable necessity", "Lack of provocation", "All elements are equal"]'::jsonb, 0, 'medium', 'Unlawful aggression is the most essential element - without it, there is no self-defense.'),
('cj_021', 'criminal_jurisprudence', 'Justifying Circumstances', 'Defense of stranger requires what additional element?', '["Defender not induced by revenge or resentment", "Blood relationship", "Employment relationship", "Friendship"]'::jsonb, 0, 'medium', 'For defense of stranger, the defender must not be induced by revenge, resentment, or other evil motive.'),
('cj_022', 'criminal_jurisprudence', 'Exempting Circumstances', 'What is the effect of an exempting circumstance?', '["No criminal liability but civil liability remains", "No criminal and civil liability", "Reduced penalty", "Increased penalty"]'::jsonb, 0, 'medium', 'Exempting circumstances remove criminal liability but civil liability may still exist.'),
('cj_023', 'criminal_jurisprudence', 'Exempting Circumstances', 'What is imbecility as an exempting circumstance?', '["Mental age of 2-7 years", "Mental age below 2 years", "Temporary insanity", "Drug-induced state"]'::jsonb, 0, 'hard', 'An imbecile has a mental age of 2-7 years, while an idiot has a mental age below 2 years.'),
('cj_024', 'criminal_jurisprudence', 'Mitigating Circumstances', 'What are privileged mitigating circumstances?', '["Circumstances that reduce penalty by degrees", "Ordinary circumstances", "Aggravating circumstances", "Alternative circumstances"]'::jsonb, 0, 'hard', 'Privileged mitigating circumstances reduce the penalty by one or two degrees (e.g., minority, incomplete self-defense).'),
('cj_025', 'criminal_jurisprudence', 'Aggravating Circumstances', 'What is treachery (alevosia)?', '["Attack ensuring no risk to offender from victim defense", "Use of superior strength", "Nighttime attack", "Group attack"]'::jsonb, 0, 'medium', 'Treachery means employing means that ensure the commission of the crime without risk from the victim''s defense.'),
('cj_026', 'criminal_jurisprudence', 'Aggravating Circumstances', 'What is evident premeditation?', '["Time to reflect between decision and execution", "Sudden impulse", "Accident", "Negligence"]'::jsonb, 0, 'medium', 'Evident premeditation requires (1) determination to commit crime, (2) act showing determination, (3) sufficient time between determination and execution.'),
('cj_027', 'criminal_jurisprudence', 'Aggravating Circumstances', 'What is recidivism?', '["Convicted twice for crimes under same title of RPC", "First-time offender", "Habitual delinquent", "Quasi-recidivist"]'::jsonb, 0, 'hard', 'A recidivist is one who, at the time of trial, has been previously convicted of a crime under the same title of the RPC.'),
('cj_028', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is the difference between murder and homicide?', '["Presence of qualifying circumstances", "Type of weapon used", "Number of victims", "Location of crime"]'::jsonb, 0, 'medium', 'Murder is homicide with qualifying circumstances like treachery, evident premeditation, or cruelty.'),
('cj_029', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is parricide?', '["Killing of parents, children, or spouse", "Killing of a stranger", "Killing during robbery", "Killing by negligence"]'::jsonb, 0, 'easy', 'Parricide is the killing of one''s father, mother, child, or spouse.'),
('cj_030', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is infanticide?', '["Killing of a child less than 3 days old", "Killing of any minor", "Abortion", "Child abuse"]'::jsonb, 0, 'medium', 'Infanticide is the killing of a child less than 3 days old (72 hours).'),
('cj_031', 'criminal_jurisprudence', 'Criminal Law Book II', 'When does homicide become murder?', '["When attended by qualifying circumstances", "When weapon is used", "When victim dies instantly", "When multiple wounds inflicted"]'::jsonb, 0, 'medium', 'Homicide becomes murder when attended by qualifying circumstances like treachery, evident premeditation, etc.'),
('cj_032', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is robbery with homicide?', '["Homicide committed by reason or on occasion of robbery", "Separate crimes of robbery and homicide", "Robbery only", "Homicide only"]'::jsonb, 0, 'medium', 'Robbery with homicide is a special complex crime where killing occurs by reason or on occasion of robbery.'),
('cj_033', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is the difference between theft and robbery?', '["Robbery involves violence or intimidation", "Amount stolen", "Time of day", "Type of property"]'::jsonb, 0, 'easy', 'Robbery involves violence against or intimidation of persons, or force upon things, while theft does not.'),
('cj_034', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is estafa?', '["Swindling through deceit", "Theft", "Robbery", "Malversation"]'::jsonb, 0, 'easy', 'Estafa (swindling) involves defrauding another through abuse of confidence, deceit, or fraudulent means.'),
('cj_035', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is qualified theft?', '["Theft by domestic servant or with grave abuse of trust", "Simple theft", "Robbery", "Carnapping"]'::jsonb, 0, 'medium', 'Qualified theft is committed by a domestic servant, or with grave abuse of confidence, or involving motor vehicles.'),
('cj_036', 'criminal_jurisprudence', 'Criminal Procedure', 'What is arraignment?', '["Reading of information to accused and entry of plea", "Trial proper", "Sentencing", "Appeal"]'::jsonb, 0, 'easy', 'Arraignment is the formal reading of the criminal information to the accused and asking for their plea.'),
('cj_037', 'criminal_jurisprudence', 'Criminal Procedure', 'What is bail?', '["Security for release of accused pending trial", "Fine imposed", "Sentence served", "Parole condition"]'::jsonb, 0, 'easy', 'Bail is the security given for the release of a person in custody to guarantee their appearance in court.'),
('cj_038', 'criminal_jurisprudence', 'Criminal Procedure', 'When is bail a matter of right?', '["Before conviction for non-capital offenses", "Always", "Never", "Only after conviction"]'::jsonb, 0, 'medium', 'Bail is a matter of right before conviction for offenses not punishable by death, reclusion perpetua, or life imprisonment.'),
('cj_039', 'criminal_jurisprudence', 'Criminal Procedure', 'What is a warrant of arrest?', '["Court order to arrest a person", "Subpoena", "Search warrant", "Commitment order"]'::jsonb, 0, 'easy', 'A warrant of arrest is a written order issued by a judge directing law enforcement to arrest a person.'),
('cj_040', 'criminal_jurisprudence', 'Criminal Procedure', 'What is the rule on warrantless arrests?', '["Allowed only under specific circumstances in Rule 113", "Always allowed", "Never allowed", "Only for felonies"]'::jsonb, 0, 'medium', 'Warrantless arrests are allowed: (1) in flagrante delicto, (2) hot pursuit, (3) escaped prisoner.'),
('cj_041', 'criminal_jurisprudence', 'Criminal Procedure', 'What is in flagrante delicto?', '["Caught in the act of committing crime", "After the crime", "Before the crime", "Planning a crime"]'::jsonb, 0, 'easy', 'In flagrante delicto means the person is caught in the actual commission of a crime.'),
('cj_042', 'criminal_jurisprudence', 'Rules of Evidence', 'What is hearsay evidence?', '["Testimony based on what others said", "Direct testimony", "Documentary evidence", "Physical evidence"]'::jsonb, 0, 'easy', 'Hearsay is testimony about what the witness heard from others, not from personal knowledge.'),
('cj_043', 'criminal_jurisprudence', 'Rules of Evidence', 'What is the fruit of the poisonous tree doctrine?', '["Evidence from illegal search is inadmissible", "All evidence is admissible", "Only direct evidence allowed", "Circumstantial evidence excluded"]'::jsonb, 0, 'hard', 'Evidence obtained as a result of an illegal search or seizure is inadmissible in court.'),
('cj_044', 'criminal_jurisprudence', 'Rules of Evidence', 'What is circumstantial evidence?', '["Evidence proving facts from which crime can be inferred", "Direct evidence", "Hearsay evidence", "Documentary evidence"]'::jsonb, 0, 'medium', 'Circumstantial evidence proves facts from which the commission of a crime may be inferred.'),
('cj_045', 'criminal_jurisprudence', 'Rules of Evidence', 'What is corpus delicti?', '["Body of the crime - proof crime was committed", "Dead body", "Murder weapon", "Confession"]'::jsonb, 0, 'medium', 'Corpus delicti is the body of the crime - proof that a crime has actually been committed.'),
('cj_046', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is rape under RA 8353?', '["Sexual assault through force, threat, or intimidation", "Only forcible intercourse", "Only against women", "Property crime"]'::jsonb, 0, 'medium', 'Rape includes sexual assault through force, threat, intimidation, or when victim is deprived of reason.'),
('cj_047', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is frustrated felony?', '["All acts done but crime not produced for causes independent of will", "Completed crime", "Attempted crime", "Impossible crime"]'::jsonb, 0, 'hard', 'Frustrated felony: offender performs all acts of execution but crime is not produced due to causes independent of his will.'),
('cj_048', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is attempted felony?', '["Overt acts started but not all acts of execution done", "Completed crime", "Frustrated crime", "Impossible crime"]'::jsonb, 0, 'hard', 'Attempted felony: offender commences directly by overt acts but does not perform all acts of execution.'),
('cj_049', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is conspiracy?', '["Agreement to commit a felony and decision to commit it", "Solo planning", "Negligent act", "Accident"]'::jsonb, 0, 'medium', 'Conspiracy exists when two or more persons agree to commit a felony and decide to commit it.'),
('cj_050', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is the effect of conspiracy on criminal liability?', '["Act of one is act of all", "Only mastermind liable", "Each liable for own acts only", "No liability"]'::jsonb, 0, 'medium', 'In conspiracy, the act of one conspirator is the act of all - all are equally liable.'),
('cj_051', 'criminal_jurisprudence', 'Penalties and Punishment', 'What is Reclusion Temporal?', '["12 years and 1 day to 20 years", "20 years and 1 day to 40 years", "6 years and 1 day to 12 years", "6 months and 1 day to 6 years"]'::jsonb, 0, 'hard', 'Reclusion Temporal has a duration of 12 years and 1 day to 20 years.'),
('cj_052', 'criminal_jurisprudence', 'Penalties and Punishment', 'What is Prision Mayor?', '["6 years and 1 day to 12 years", "12 years and 1 day to 20 years", "6 months and 1 day to 6 years", "1 month and 1 day to 6 months"]'::jsonb, 0, 'hard', 'Prision Mayor has a duration of 6 years and 1 day to 12 years.'),
('cj_053', 'criminal_jurisprudence', 'Penalties and Punishment', 'What is Prision Correccional?', '["6 months and 1 day to 6 years", "6 years and 1 day to 12 years", "1 month and 1 day to 6 months", "1 day to 30 days"]'::jsonb, 0, 'hard', 'Prision Correccional has a duration of 6 months and 1 day to 6 years.'),
('cj_054', 'criminal_jurisprudence', 'Penalties and Punishment', 'What is Arresto Mayor?', '["1 month and 1 day to 6 months", "6 months and 1 day to 6 years", "1 day to 30 days", "6 years and 1 day to 12 years"]'::jsonb, 0, 'medium', 'Arresto Mayor has a duration of 1 month and 1 day to 6 months.'),
('cj_055', 'criminal_jurisprudence', 'Penalties and Punishment', 'What is Arresto Menor?', '["1 day to 30 days", "1 month and 1 day to 6 months", "6 months and 1 day to 6 years", "31 days to 6 months"]'::jsonb, 0, 'medium', 'Arresto Menor has a duration of 1 day to 30 days.'),
('cj_056', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is the penalty for serious physical injuries?', '["Prision Mayor", "Prision Correccional", "Arresto Mayor", "Arresto Menor"]'::jsonb, 0, 'medium', 'Serious physical injuries are punishable by Prision Mayor under Article 263 of the RPC.'),
('cj_057', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is direct assault?', '["Attack on person in authority while performing duties", "Simple assault", "Robbery", "Homicide"]'::jsonb, 0, 'medium', 'Direct assault is attacking or using force on a person in authority or agent while performing official duties.'),
('cj_058', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is resistance and disobedience?', '["Refusing to obey lawful orders of authority", "Direct assault", "Sedition", "Rebellion"]'::jsonb, 0, 'medium', 'Resistance and disobedience is refusing to obey the lawful orders of a person in authority.'),
('cj_059', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is the crime of alarm and scandal?', '["Discharging firearm or causing serious disturbance", "Theft", "Robbery", "Murder"]'::jsonb, 0, 'easy', 'Alarm and scandal includes discharging firearms, causing serious disturbance, or orgiastic behavior.'),
('cj_060', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is illegal possession of firearms under RA 10591?', '["Possessing firearm without license", "Licensed firearm possession", "Carrying licensed firearm", "Selling licensed firearms"]'::jsonb, 0, 'easy', 'Illegal possession of firearms means possessing a firearm without the required license or permit.'),
('le_001', 'law_enforcement', 'Police Organization and Administration', 'What is the primary function of the Philippine National Police?', '["Law enforcement and public safety", "Military defense", "Tax collection", "Immigration control"]'::jsonb, 0, 'easy', 'The PNP is primarily responsible for law enforcement and maintaining peace and order.'),
('le_002', 'law_enforcement', 'Police Organization and Administration', 'Who is the Chief of the Philippine National Police appointed by?', '["The President", "The Senate", "The NAPOLCOM", "The DILG Secretary"]'::jsonb, 0, 'easy', 'The Chief PNP is appointed by the President of the Philippines.'),
('le_003', 'law_enforcement', 'Police Planning', 'What type of plan covers a period of one year or less?', '["Short-range plan", "Medium-range plan", "Long-range plan", "Strategic plan"]'::jsonb, 0, 'easy', 'Short-range plans cover a period of one year or less.'),
('le_004', 'law_enforcement', 'Police Patrol Operations', 'What is the most common type of patrol?', '["Foot patrol", "Horse patrol", "Helicopter patrol", "Bicycle patrol"]'::jsonb, 0, 'easy', 'Foot patrol is the oldest and most common type of patrol.'),
('le_005', 'law_enforcement', 'Police Intelligence', 'What does HUMINT stand for?', '["Human Intelligence", "Humanitarian Intelligence", "Humane Intelligence", "Humble Intelligence"]'::jsonb, 0, 'medium', 'HUMINT stands for Human Intelligence, gathered from human sources.'),
('le_006', 'law_enforcement', 'Industrial Security Administration', 'What is the primary purpose of industrial security?', '["Protection of assets and personnel", "Profit maximization", "Marketing products", "Employee recruitment"]'::jsonb, 0, 'easy', 'Industrial security aims to protect company assets, personnel, and information.'),
('le_007', 'law_enforcement', 'Comparative Police System', 'Which country has a decentralized police system?', '["United States", "France", "Japan", "Italy"]'::jsonb, 0, 'medium', 'The United States has a decentralized police system with federal, state, and local agencies.'),
('le_008', 'law_enforcement', 'Police Communication System', 'What is the international distress signal in radio communication?', '["Mayday", "SOS", "Help", "911"]'::jsonb, 0, 'medium', 'Mayday is the international voice distress signal used in radio communication.'),
('le_009', 'law_enforcement', 'Police Personnel Management', 'What is the minimum educational requirement to become a police officer in the Philippines?', '["Bachelor''s degree", "High school diploma", "Master''s degree", "Vocational course"]'::jsonb, 0, 'easy', 'A bachelor''s degree is required to become a police officer in the Philippines.'),
('le_010', 'law_enforcement', 'Police Records Management', 'What is the purpose of police blotter?', '["Record daily police activities", "Store criminal evidence", "Train new officers", "Plan operations"]'::jsonb, 0, 'easy', 'The police blotter is an official record of daily police activities and incidents.'),
('le_011', 'law_enforcement', 'Police Organization and Administration', 'What law created the Philippine National Police?', '["RA 6975", "RA 8551", "RA 9165", "RA 10591"]'::jsonb, 0, 'medium', 'RA 6975 (DILG Act of 1990) established the Philippine National Police under the DILG.'),
('le_012', 'law_enforcement', 'Police Organization and Administration', 'What is NAPOLCOM?', '["National Police Commission", "National Police Command", "National Police Council", "National Police Committee"]'::jsonb, 0, 'easy', 'NAPOLCOM is the National Police Commission that exercises administrative control over the PNP.'),
('le_013', 'law_enforcement', 'Police Organization and Administration', 'What is the chain of command in the PNP?', '["Line of authority from top to bottom", "Horizontal communication", "Informal communication", "External communication"]'::jsonb, 0, 'easy', 'Chain of command is the line of authority that extends from the top to the bottom of an organization.'),
('le_014', 'law_enforcement', 'Police Organization and Administration', 'What is unity of command?', '["One subordinate reports to one superior", "Multiple supervisors", "Team leadership", "Democratic leadership"]'::jsonb, 0, 'medium', 'Unity of command means each subordinate should receive orders from only one superior.'),
('le_015', 'law_enforcement', 'Police Organization and Administration', 'What is span of control?', '["Number of subordinates one can supervise", "Type of leadership", "Communication method", "Training approach"]'::jsonb, 0, 'medium', 'Span of control refers to the number of subordinates a supervisor can effectively manage.'),
('le_016', 'law_enforcement', 'Police Patrol Operations', 'What is the primary purpose of police patrol?', '["Crime prevention and detection", "Revenue collection", "Political activity", "Entertainment"]'::jsonb, 0, 'easy', 'Police patrol aims to prevent crime, detect criminal activity, and maintain public order.'),
('le_017', 'law_enforcement', 'Police Patrol Operations', 'What is beat patrol?', '["Patrol of a specific geographical area", "Random patrol", "Highway patrol", "Air patrol"]'::jsonb, 0, 'easy', 'Beat patrol involves regularly patrolling a specific geographical area or route.'),
('le_018', 'law_enforcement', 'Police Patrol Operations', 'What is motorized patrol?', '["Patrol using vehicles", "Foot patrol", "Horse patrol", "Bicycle patrol"]'::jsonb, 0, 'easy', 'Motorized patrol uses motor vehicles to cover larger areas more efficiently.'),
('le_019', 'law_enforcement', 'Police Patrol Operations', 'What is the advantage of foot patrol?', '["Better community interaction", "Faster response", "Wider coverage", "Lower fatigue"]'::jsonb, 0, 'easy', 'Foot patrol allows officers to interact closely with the community and notice details.'),
('le_020', 'law_enforcement', 'Police Patrol Operations', 'What is directed patrol?', '["Patrol focused on high-crime areas", "Random patrol", "Routine patrol", "Social patrol"]'::jsonb, 0, 'medium', 'Directed patrol concentrates patrol resources on specific high-crime areas or times.'),
('le_021', 'law_enforcement', 'Police Intelligence', 'What is SIGINT?', '["Signals Intelligence", "Signature Intelligence", "Single Intelligence", "Simple Intelligence"]'::jsonb, 0, 'medium', 'SIGINT is Signals Intelligence gathered from intercepting electronic communications.'),
('le_022', 'law_enforcement', 'Police Intelligence', 'What is OSINT?', '["Open Source Intelligence", "Official Source Intelligence", "Operational Source Intelligence", "Online Source Intelligence"]'::jsonb, 0, 'medium', 'OSINT is Open Source Intelligence gathered from publicly available sources.'),
('le_023', 'law_enforcement', 'Police Intelligence', 'What is covert operation?', '["Secret operation to gather information", "Open police activity", "Public announcement", "Media briefing"]'::jsonb, 0, 'easy', 'Covert operation is a secret activity conducted to gather intelligence or apprehend criminals.'),
('le_024', 'law_enforcement', 'Police Intelligence', 'What is surveillance?', '["Covert observation of persons or places", "Public interview", "Open investigation", "Press conference"]'::jsonb, 0, 'easy', 'Surveillance is the covert observation of persons, places, or activities.'),
('le_025', 'law_enforcement', 'Police Intelligence', 'What is the intelligence cycle?', '["Planning, Collection, Processing, Dissemination", "Arrest, Charge, Trial, Sentence", "Report, Investigate, Solve, Close", "Patrol, Respond, Arrest, Report"]'::jsonb, 0, 'hard', 'The intelligence cycle includes Planning, Collection, Processing/Analysis, and Dissemination.'),
('le_026', 'law_enforcement', 'Police Planning', 'What is a medium-range plan?', '["Plan covering 1 to 5 years", "Plan covering less than 1 year", "Plan covering more than 5 years", "Daily plan"]'::jsonb, 0, 'medium', 'Medium-range plans typically cover a period of 1 to 5 years.'),
('le_027', 'law_enforcement', 'Police Planning', 'What is a long-range plan?', '["Plan covering more than 5 years", "Plan covering 1 to 5 years", "Plan covering less than 1 year", "Weekly plan"]'::jsonb, 0, 'medium', 'Long-range or strategic plans cover a period of more than 5 years.'),
('le_028', 'law_enforcement', 'Police Planning', 'What is an operational plan?', '["Plan for specific operations or activities", "Long-term strategic plan", "Budget plan", "Personnel plan"]'::jsonb, 0, 'easy', 'Operational plans detail specific actions for carrying out tactical objectives.'),
('le_029', 'law_enforcement', 'Police Planning', 'What is SWOT analysis?', '["Strengths, Weaknesses, Opportunities, Threats", "Strategy, Work, Operation, Tactics", "System, Way, Order, Time", "Skill, Will, Opportunity, Task"]'::jsonb, 0, 'medium', 'SWOT analysis examines internal Strengths and Weaknesses, and external Opportunities and Threats.'),
('le_030', 'law_enforcement', 'Police Planning', 'What is contingency planning?', '["Planning for emergencies or unexpected events", "Regular planning", "Budget planning", "Personnel planning"]'::jsonb, 0, 'medium', 'Contingency planning prepares for unexpected events or emergencies.'),
('le_031', 'law_enforcement', 'Police Personnel Management', 'What is the minimum height requirement for male PNP applicants?', '["5 feet 4 inches", "5 feet 2 inches", "5 feet 6 inches", "5 feet"]'::jsonb, 0, 'medium', 'Male PNP applicants must be at least 5 feet 4 inches (162 cm) tall.'),
('le_032', 'law_enforcement', 'Police Personnel Management', 'What is the minimum height requirement for female PNP applicants?', '["5 feet 2 inches", "5 feet", "5 feet 4 inches", "4 feet 11 inches"]'::jsonb, 0, 'medium', 'Female PNP applicants must be at least 5 feet 2 inches (157 cm) tall.'),
('le_033', 'law_enforcement', 'Police Personnel Management', 'What is the age requirement for PNP applicants?', '["21 to 30 years old", "18 to 25 years old", "25 to 35 years old", "18 to 40 years old"]'::jsonb, 0, 'medium', 'PNP applicants must be at least 21 years old but not more than 30 years old.'),
('le_034', 'law_enforcement', 'Police Personnel Management', 'What is the mandatory retirement age for PNP members?', '["56 years old", "60 years old", "65 years old", "50 years old"]'::jsonb, 0, 'medium', 'The mandatory retirement age for PNP uniformed personnel is 56 years old.'),
('le_035', 'law_enforcement', 'Police Personnel Management', 'What is NEAP?', '["National Eligibility Aptitude Test", "National Entrance Assessment Program", "National Examination for Applicants", "National Entry Application Process"]'::jsonb, 0, 'hard', 'NEAP is the National Eligibility Aptitude Test for PNP applicants.'),
('le_036', 'law_enforcement', 'Industrial Security Administration', 'What is physical security?', '["Protection of physical assets and facilities", "Personal security", "Document security", "Communication security"]'::jsonb, 0, 'easy', 'Physical security involves protecting buildings, facilities, and physical assets.'),
('le_037', 'law_enforcement', 'Industrial Security Administration', 'What is document security?', '["Protection of classified documents", "Physical security", "Personal security", "Electronic security"]'::jsonb, 0, 'easy', 'Document security involves protecting classified and sensitive documents from unauthorized access.'),
('le_038', 'law_enforcement', 'Industrial Security Administration', 'What is personnel security?', '["Screening and monitoring of employees", "Building security", "Document security", "Vehicle security"]'::jsonb, 0, 'easy', 'Personnel security involves background checks and monitoring of employees.'),
('le_039', 'law_enforcement', 'Industrial Security Administration', 'What is access control?', '["Regulating entry to facilities or areas", "Traffic control", "Crowd control", "Border control"]'::jsonb, 0, 'easy', 'Access control regulates who can enter specific facilities, areas, or systems.'),
('le_040', 'law_enforcement', 'Industrial Security Administration', 'What is a security survey?', '["Assessment of security vulnerabilities", "Employee survey", "Customer survey", "Market survey"]'::jsonb, 0, 'medium', 'A security survey is a comprehensive analysis of security vulnerabilities and risks.')
INSERT INTO questions (id, subject, topic, question_text, options, correct_answer_index, difficulty, explanation) VALUES
('le_041', 'law_enforcement', 'Comparative Police System', 'What is a centralized police system?', '["Single national police force", "Multiple independent forces", "Local police only", "Private police only"]'::jsonb, 0, 'medium', 'A centralized system has one national police force controlled by the central government.'),
('le_042', 'law_enforcement', 'Comparative Police System', 'Which country has the Scotland Yard?', '["United Kingdom", "United States", "France", "Germany"]'::jsonb, 0, 'easy', 'Scotland Yard is the headquarters of the Metropolitan Police Service in London, UK.'),
('le_043', 'law_enforcement', 'Comparative Police System', 'What is INTERPOL?', '["International Criminal Police Organization", "International Police", "Internal Police", "Internet Police"]'::jsonb, 0, 'easy', 'INTERPOL is the International Criminal Police Organization that facilitates international police cooperation.'),
('le_044', 'law_enforcement', 'Comparative Police System', 'What country has the Gendarmerie?', '["France", "United States", "Philippines", "Japan"]'::jsonb, 0, 'medium', 'France has the Gendarmerie Nationale, a military force with law enforcement duties.'),
('le_045', 'law_enforcement', 'Comparative Police System', 'What is the FBI?', '["Federal Bureau of Investigation", "Federal Bureau of Intelligence", "Federal Board of Investigation", "Federal Bureau of Inspection"]'::jsonb, 0, 'easy', 'The FBI is the Federal Bureau of Investigation, the principal federal law enforcement agency in the US.'),
('le_046', 'law_enforcement', 'Police Communication System', 'What is the phonetic alphabet for letter A?', '["Alpha", "Adam", "Able", "Apple"]'::jsonb, 0, 'easy', 'In the NATO phonetic alphabet, A is represented by Alpha.'),
('le_047', 'law_enforcement', 'Police Communication System', 'What is the phonetic alphabet for letter B?', '["Bravo", "Baker", "Boy", "Beta"]'::jsonb, 0, 'easy', 'In the NATO phonetic alphabet, B is represented by Bravo.'),
('le_048', 'law_enforcement', 'Police Communication System', 'What does "10-4" mean in police radio codes?', '["Acknowledgment/OK", "Emergency", "In pursuit", "Need backup"]'::jsonb, 0, 'easy', '10-4 means acknowledgment or "message received and understood."'),
('le_049', 'law_enforcement', 'Police Communication System', 'What is two-way radio communication?', '["Both parties can transmit and receive", "One-way transmission only", "Written communication", "Face-to-face only"]'::jsonb, 0, 'easy', 'Two-way radio allows both parties to transmit and receive messages.'),
('le_050', 'law_enforcement', 'Police Communication System', 'What is the purpose of police radio communication?', '["Rapid coordination and dispatch", "Entertainment", "Public announcement", "Commercial advertising"]'::jsonb, 0, 'easy', 'Police radio enables rapid communication for coordination, dispatch, and emergency response.'),
('le_051', 'law_enforcement', 'Police Organization and Administration', 'What is RA 8551?', '["PNP Reform and Reorganization Act of 1998", "DILG Act of 1990", "Dangerous Drugs Act", "Firearms Act"]'::jsonb, 0, 'hard', 'RA 8551 is the PNP Reform and Reorganization Act of 1998.'),
('le_052', 'law_enforcement', 'Police Organization and Administration', 'What is the lowest rank in the PNP?', '["Patrolman/Patrolwoman", "Police Corporal", "Police Staff Sergeant", "Police Master Sergeant"]'::jsonb, 0, 'easy', 'Patrolman/Patrolwoman is the entry-level rank in the PNP.'),
('le_053', 'law_enforcement', 'Police Organization and Administration', 'What is the highest rank in the PNP?', '["Police General", "Police Lieutenant General", "Police Major General", "Police Director"]'::jsonb, 0, 'easy', 'Police General is the highest rank in the PNP, held by the Chief PNP.'),
('le_054', 'law_enforcement', 'Police Organization and Administration', 'How many Police Regional Offices are there in the Philippines?', '["17 PROs", "15 PROs", "12 PROs", "20 PROs"]'::jsonb, 0, 'medium', 'There are 17 Police Regional Offices (PROs) corresponding to the 17 regions of the Philippines.'),
('le_055', 'law_enforcement', 'Police Patrol Operations', 'What is the KATARUNGANG PAMBARANGAY?', '["Barangay justice system for dispute resolution", "Police patrol", "Court system", "Prison system"]'::jsonb, 0, 'medium', 'Katarungang Pambarangay is the barangay justice system for amicable settlement of disputes.'),
('le_056', 'law_enforcement', 'Police Intelligence', 'What is counter-intelligence?', '["Activities to prevent espionage", "Collecting intelligence", "Sharing intelligence", "Publishing intelligence"]'::jsonb, 0, 'medium', 'Counter-intelligence involves activities to prevent enemy espionage and sabotage.'),
('le_057', 'law_enforcement', 'Police Intelligence', 'What is an informant?', '["Person providing information to police", "Police officer", "Judge", "Prosecutor"]'::jsonb, 0, 'easy', 'An informant is a person who provides information to law enforcement, often confidentially.'),
('le_058', 'law_enforcement', 'Police Personnel Management', 'What is the PNP SALN?', '["Statement of Assets, Liabilities, and Net Worth", "Statement of Annual Leave and Notice", "System of Administrative Leave and Notice", "Statement of Accountability and Legal Notice"]'::jsonb, 0, 'medium', 'SALN is the Statement of Assets, Liabilities, and Net Worth required from all PNP members.'),
('le_059', 'law_enforcement', 'Industrial Security Administration', 'What is CCTV used for in security?', '["Surveillance and monitoring", "Communication", "Transportation", "Entertainment"]'::jsonb, 0, 'easy', 'CCTV (Closed-Circuit Television) is used for surveillance and monitoring of areas.'),
('le_060', 'law_enforcement', 'Police Records Management', 'What is a rogues gallery?', '["Collection of criminal photographs", "Police station", "Courtroom", "Prison cell"]'::jsonb, 0, 'medium', 'A rogues gallery is a collection of photographs of known criminals for identification.'),
('cr_001', 'criminalistics', 'Personal Identification', 'What is the most reliable method of personal identification?', '["Fingerprints", "Facial features", "Height and weight", "Hair color"]'::jsonb, 0, 'easy', 'Fingerprints are unique to each individual and remain unchanged throughout life.'),
('cr_002', 'criminalistics', 'Dactyloscopy', 'What is the study of fingerprints called?', '["Dactyloscopy", "Poroscopy", "Chiroscopy", "Podoscopy"]'::jsonb, 0, 'easy', 'Dactyloscopy is the scientific study of fingerprints for identification purposes.'),
('cr_003', 'criminalistics', 'Forensic Ballistics', 'What is the study of firearms and ammunition called?', '["Forensic Ballistics", "Forensic Chemistry", "Forensic Biology", "Forensic Medicine"]'::jsonb, 0, 'easy', 'Forensic Ballistics is the science dealing with firearms, bullets, and related evidence.'),
('cr_004', 'criminalistics', 'Questioned Documents Examination', 'What is a questioned document?', '["A document whose authenticity is in doubt", "A legal document", "A notarized document", "An official government document"]'::jsonb, 0, 'easy', 'A questioned document is any document whose authenticity, origin, or authorship is disputed.'),
('cr_005', 'criminalistics', 'Polygraph and Lie Detection', 'What does a polygraph machine measure?', '["Physiological responses", "Brain waves only", "Voice patterns only", "Eye movements only"]'::jsonb, 0, 'medium', 'A polygraph measures physiological responses including blood pressure, pulse, respiration, and skin conductivity.'),
('cr_006', 'criminalistics', 'Legal Medicine', 'What is rigor mortis?', '["Stiffening of muscles after death", "Body temperature drop", "Skin discoloration", "Blood pooling"]'::jsonb, 0, 'medium', 'Rigor mortis is the stiffening of muscles that occurs after death due to chemical changes.'),
('cr_007', 'criminalistics', 'Police Photography', 'What is the purpose of crime scene photography?', '["Document and preserve evidence", "Artistic expression", "Media publication", "Entertainment"]'::jsonb, 0, 'easy', 'Crime scene photography documents and preserves the scene as evidence for investigation and court.'),
('cr_008', 'criminalistics', 'DNA Analysis', 'What biological samples can be used for DNA analysis?', '["Blood, saliva, hair", "Only blood", "Only saliva", "Only skin cells"]'::jsonb, 0, 'easy', 'DNA can be extracted from various biological samples including blood, saliva, hair, skin cells, and more.'),
('cr_009', 'criminalistics', 'Forensic Chemistry', 'What test is used to detect the presence of blood?', '["Luminol test", "Litmus test", "pH test", "Acid test"]'::jsonb, 0, 'medium', 'The Luminol test is commonly used to detect trace amounts of blood at crime scenes.'),
('cr_010', 'criminalistics', 'Dactyloscopy', 'What are the three main fingerprint patterns?', '["Loop, Whorl, Arch", "Circle, Square, Triangle", "Spiral, Linear, Curved", "Plain, Tented, Mixed"]'::jsonb, 0, 'medium', 'The three main fingerprint patterns are Loop (60-65%), Whorl (30-35%), and Arch (5%).'),
('cr_011', 'criminalistics', 'Dactyloscopy', 'What is the most common fingerprint pattern?', '["Loop", "Whorl", "Arch", "Composite"]'::jsonb, 0, 'easy', 'Loop is the most common fingerprint pattern, occurring in 60-65% of all fingerprints.'),
('cr_012', 'criminalistics', 'Dactyloscopy', 'What is poroscopy?', '["Study of sweat pores on fingerprints", "Study of footprints", "Study of palm prints", "Study of lip prints"]'::jsonb, 0, 'hard', 'Poroscopy is the study of sweat pores on fingerprint ridges for identification.'),
('cr_013', 'criminalistics', 'Dactyloscopy', 'What is a latent fingerprint?', '["Invisible print requiring development", "Visible print", "Plastic print", "Bloody print"]'::jsonb, 0, 'medium', 'Latent prints are invisible fingerprints left by natural skin oils that require development to be seen.'),
('cr_014', 'criminalistics', 'Dactyloscopy', 'What is a patent fingerprint?', '["Visible print made with foreign substance", "Invisible print", "Print on soft surface", "Partial print"]'::jsonb, 0, 'medium', 'Patent prints are visible fingerprints made when fingers contaminated with ink, blood, or other substances touch a surface.'),
('cr_015', 'criminalistics', 'Dactyloscopy', 'What is a plastic fingerprint?', '["3D impression on soft surface", "Latent print", "Patent print", "Partial print"]'::jsonb, 0, 'medium', 'Plastic prints are three-dimensional impressions left on soft surfaces like wax, soap, or putty.'),
('cr_016', 'criminalistics', 'Dactyloscopy', 'What powder is commonly used to develop latent fingerprints on dark surfaces?', '["White or gray powder", "Black powder", "Red powder", "Blue powder"]'::jsonb, 0, 'medium', 'Light-colored powders like white or gray are used on dark surfaces for contrast.'),
('cr_017', 'criminalistics', 'Dactyloscopy', 'Who is the Father of Fingerprint Identification?', '["Sir Francis Galton", "Alphonse Bertillon", "Juan Vucetich", "Sir Edward Henry"]'::jsonb, 0, 'hard', 'Sir Francis Galton established the scientific basis for fingerprint identification.'),
('cr_018', 'criminalistics', 'Dactyloscopy', 'What is the Henry Classification System?', '["Fingerprint classification system using all ten fingers", "Single finger system", "Palm print system", "Footprint system"]'::jsonb, 0, 'hard', 'The Henry System classifies fingerprints using patterns from all ten fingers.'),
('cr_019', 'criminalistics', 'Forensic Ballistics', 'What is interior ballistics?', '["Study of projectile inside the firearm", "Study of projectile in flight", "Study of projectile impact", "Study of gunshot wounds"]'::jsonb, 0, 'medium', 'Interior ballistics studies the projectile behavior inside the firearm barrel.'),
('cr_020', 'criminalistics', 'Forensic Ballistics', 'What is exterior ballistics?', '["Study of projectile in flight", "Study of projectile inside firearm", "Study of projectile impact", "Study of gunpowder"]'::jsonb, 0, 'medium', 'Exterior ballistics studies the projectile behavior during flight through the air.'),
('cr_021', 'criminalistics', 'Forensic Ballistics', 'What is terminal ballistics?', '["Study of projectile impact on target", "Study of projectile in flight", "Study of projectile inside firearm", "Study of cartridge"]'::jsonb, 0, 'medium', 'Terminal ballistics studies the projectile behavior upon impact with the target.'),
('cr_022', 'criminalistics', 'Forensic Ballistics', 'What is rifling?', '["Spiral grooves inside gun barrel", "Gun sight", "Trigger mechanism", "Magazine"]'::jsonb, 0, 'medium', 'Rifling consists of spiral grooves cut inside the barrel to spin the bullet for accuracy.'),
('cr_023', 'criminalistics', 'Forensic Ballistics', 'What are lands and grooves?', '["Raised and cut areas in rifle barrel", "Types of ammunition", "Gun parts", "Cartridge components"]'::jsonb, 0, 'medium', 'Lands are the raised portions between grooves in a rifled barrel.'),
('cr_024', 'criminalistics', 'Forensic Ballistics', 'What is a cartridge?', '["Complete unit of ammunition", "Bullet only", "Gunpowder only", "Primer only"]'::jsonb, 0, 'easy', 'A cartridge is the complete unit containing bullet, case, propellant, and primer.'),
('cr_025', 'criminalistics', 'Forensic Ballistics', 'What is the primer?', '["Ignition component of cartridge", "Bullet", "Propellant", "Case"]'::jsonb, 0, 'easy', 'The primer is the component that ignites when struck, igniting the propellant.'),
('cr_026', 'criminalistics', 'Forensic Ballistics', 'What is caliber?', '["Diameter of gun bore or bullet", "Length of barrel", "Weight of gun", "Number of rounds"]'::jsonb, 0, 'easy', 'Caliber refers to the internal diameter of the gun barrel or the diameter of the bullet.'),
('cr_027', 'criminalistics', 'Forensic Ballistics', 'What is gunshot residue (GSR)?', '["Particles deposited when gun is fired", "Bullet fragments", "Blood spatter", "Fingerprints"]'::jsonb, 0, 'easy', 'GSR consists of particles expelled from a firearm when discharged.'),
('cr_028', 'criminalistics', 'Forensic Ballistics', 'What is the comparison microscope used for in ballistics?', '["Comparing bullets and cartridge cases", "Examining fingerprints", "Analyzing blood", "Testing drugs"]'::jsonb, 0, 'medium', 'The comparison microscope allows side-by-side comparison of bullets or cartridge cases.'),
('cr_029', 'criminalistics', 'Questioned Documents Examination', 'What is handwriting analysis?', '["Examination of writing characteristics", "Reading documents", "Typing analysis", "Voice analysis"]'::jsonb, 0, 'easy', 'Handwriting analysis examines the unique characteristics of a person''s writing.'),
('cr_030', 'criminalistics', 'Questioned Documents Examination', 'What is a forged signature?', '["Imitation of another person''s signature", "Original signature", "Stamped signature", "Digital signature"]'::jsonb, 0, 'easy', 'A forged signature is a fraudulent imitation of another person''s genuine signature.'),
('cr_031', 'criminalistics', 'Questioned Documents Examination', 'What is an exemplar in document examination?', '["Known sample for comparison", "Questioned document", "Forged document", "Blank document"]'::jsonb, 0, 'medium', 'An exemplar is a known sample of handwriting used for comparison with questioned documents.'),
('cr_032', 'criminalistics', 'Questioned Documents Examination', 'What is an alteration in document examination?', '["Change made to original document", "Original writing", "Copy of document", "Blank page"]'::jsonb, 0, 'easy', 'An alteration is any change made to a document after its original creation.'),
('cr_033', 'criminalistics', 'Questioned Documents Examination', 'What is obliteration?', '["Covering or removing original writing", "Adding new writing", "Copying writing", "Signing a document"]'::jsonb, 0, 'medium', 'Obliteration involves covering or removing original writing, often to conceal information.'),
('cr_034', 'criminalistics', 'Legal Medicine', 'What is livor mortis?', '["Discoloration of skin due to blood pooling", "Muscle stiffening", "Body cooling", "Decomposition"]'::jsonb, 0, 'medium', 'Livor mortis is the purplish discoloration of skin due to blood settling after death.'),
