('cr_039', 'criminalistics', 'Legal Medicine', 'What is cause of death?', '["Disease or injury that caused death", "Manner of death", "Time of death", "Place of death"]'::jsonb, 0, 'easy', 'Cause of death is the specific disease, injury, or condition that resulted in death.'),
('cr_040', 'criminalistics', 'Legal Medicine', 'What is cadaveric spasm?', '["Instant rigidity at moment of death", "Gradual stiffening", "Muscle relaxation", "Decomposition"]'::jsonb, 0, 'hard', 'Cadaveric spasm is instant rigidity occurring at the moment of death, usually due to violent death.'),
('cr_041', 'criminalistics', 'Polygraph and Lie Detection', 'What is the scientific name for lie detector?', '["Polygraph", "Spectrograph", "Cardiograph", "Electroencephalograph"]'::jsonb, 0, 'easy', 'The polygraph is the scientific instrument commonly called the lie detector.'),
('cr_042', 'criminalistics', 'Polygraph and Lie Detection', 'What physiological responses does a polygraph measure?', '["Blood pressure, respiration, skin conductivity", "Only heart rate", "Only breathing", "Only sweating"]'::jsonb, 0, 'medium', 'Polygraph measures blood pressure, pulse, respiration, and galvanic skin response.'),
('cr_043', 'criminalistics', 'Polygraph and Lie Detection', 'What is the relevant-irrelevant test in polygraph?', '["Comparing responses to relevant and irrelevant questions", "Single question test", "Voice test", "Written test"]'::jsonb, 0, 'hard', 'The relevant-irrelevant test compares physiological responses between crime-related and neutral questions.'),
('cr_044', 'criminalistics', 'Police Photography', 'What is the first photograph taken at a crime scene?', '["Overview or general shot", "Close-up", "Evidence shot", "Exit shot"]'::jsonb, 0, 'easy', 'The first photograph should be an overview showing the entire crime scene.'),
