('cr_046', 'criminalistics', 'Police Photography', 'Why use a scale in evidence photography?', '["To show size of evidence", "For artistic effect", "To hide evidence", "For lighting"]'::jsonb, 0, 'easy', 'A scale or ruler shows the actual size of evidence in photographs.'),
('cr_047', 'criminalistics', 'DNA Analysis', 'What does DNA stand for?', '["Deoxyribonucleic Acid", "Deoxyribonuclear Acid", "Diribonucleic Acid", "Dinucleic Acid"]'::jsonb, 0, 'easy', 'DNA stands for Deoxyribonucleic Acid, the genetic material in cells.'),
