('cr_049', 'criminalistics', 'DNA Analysis', 'What is PCR in DNA analysis?', '["Polymerase Chain Reaction", "Protein Chain Reaction", "Physical Chemical Reaction", "Primary Cell Replication"]'::jsonb, 0, 'hard', 'PCR (Polymerase Chain Reaction) amplifies small amounts of DNA for analysis.'),
('cr_050', 'criminalistics', 'Forensic Chemistry', 'What is the presumptive test for blood?', '["Benzidine test", "Marquis test", "Scott test", "Duquenois-Levine test"]'::jsonb, 0, 'hard', 'The Benzidine test is a presumptive test that indicates the possible presence of blood.'),
('cr_051', 'criminalistics', 'Forensic Chemistry', 'What is chromatography?', '["Technique to separate mixtures", "Photography technique", "Fingerprint technique", "Ballistics technique"]'::jsonb, 0, 'medium', 'Chromatography is a laboratory technique for separating mixtures into components.'),
('cr_052', 'criminalistics', 'Forensic Chemistry', 'What test is used for marijuana identification?', '["Duquenois-Levine test", "Marquis test", "Scott test", "Benzidine test"]'::jsonb, 0, 'hard', 'The Duquenois-Levine test is a color test used to presumptively identify marijuana.'),
('cr_053', 'criminalistics', 'Forensic Chemistry', 'What test is used for cocaine identification?', '["Scott test", "Marquis test", "Duquenois-Levine test", "Benzidine test"]'::jsonb, 0, 'hard', 'The Scott test (cobalt thiocyanate) is used to presumptively identify cocaine.'),
('cr_054', 'criminalistics', 'Forensic Chemistry', 'What is the Marquis test used for?', '["Testing for opiates and amphetamines", "Testing for marijuana", "Testing for cocaine", "Testing for blood"]'::jsonb, 0, 'hard', 'The Marquis test is used to presumptively identify opiates, amphetamines, and similar drugs.'),
