('cr_058', 'criminalistics', 'Legal Medicine', 'What is toxicology?', '["Study of poisons", "Study of diseases", "Study of wounds", "Study of bones"]'::jsonb, 0, 'easy', 'Toxicology is the study of poisons and their effects on the body.'),
('cr_059', 'criminalistics', 'Legal Medicine', 'What is the examination of bones called?', '["Forensic anthropology", "Forensic odontology", "Forensic pathology", "Forensic toxicology"]'::jsonb, 0, 'medium', 'Forensic anthropology involves the examination of skeletal remains.'),
('cr_060', 'criminalistics', 'Legal Medicine', 'What is forensic odontology?', '["Identification using teeth", "Identification using bones", "Identification using blood", "Identification using hair"]'::jsonb, 0, 'medium', 'Forensic odontology uses dental records and teeth for identification.'),
('cd_001', 'crime_detection', 'Fundamentals of Criminal Investigation', 'What are the 3 I''s of criminal investigation?', '["Information, Interrogation, Instrumentation", "Interview, Inspect, Investigate", "Identify, Isolate, Interrogate", "Input, Investigate, Interpret"]'::jsonb, 0, 'medium', 'The 3 I''s are Information (gathering data), Interrogation (questioning), and Instrumentation (forensic tools).'),
('cd_002', 'crime_detection', 'Crime Scene Investigation', 'What is the first priority at a crime scene?', '["Safety and scene security", "Collecting evidence", "Taking photographs", "Interviewing witnesses"]'::jsonb, 0, 'easy', 'Safety and securing the crime scene is always the first priority to prevent contamination.'),
('cd_003', 'crime_detection', 'Traffic Management', 'What is the purpose of traffic management?', '["Ensure safe and efficient traffic flow", "Issue more tickets", "Generate revenue", "Reduce vehicle numbers"]'::jsonb, 0, 'easy', 'Traffic management aims to ensure safe, orderly, and efficient movement of vehicles and pedestrians.'),
('cd_004', 'crime_detection', 'Special Crime Investigation', 'What is kidnapping for ransom classified as?', '["Heinous crime", "Simple crime", "Misdemeanor", "Civil offense"]'::jsonb, 0, 'easy', 'Kidnapping for ransom is classified as a heinous crime punishable by severe penalties.'),
('cd_005', 'crime_detection', 'Drug Education and Vice Control', 'What is the most commonly abused illegal drug in the Philippines?', '["Methamphetamine (Shabu)", "Marijuana", "Cocaine", "Heroin"]'::jsonb, 0, 'easy', 'Methamphetamine hydrochloride (Shabu) is the most commonly abused illegal drug in the Philippines.'),
('cd_006', 'crime_detection', 'Fire Technology', 'What are the three elements of fire?', '["Heat, Fuel, Oxygen", "Water, Air, Earth", "Fire, Wind, Light", "Gas, Liquid, Solid"]'::jsonb, 0, 'easy', 'The fire triangle consists of Heat, Fuel, and Oxygen - all three are needed for fire.'),
('cd_007', 'crime_detection', 'Arson Investigation', 'What is arson?', '["Intentional burning of property", "Accidental fire", "Natural disaster", "Electrical malfunction"]'::jsonb, 0, 'easy', 'Arson is the intentional and malicious burning of property.'),
('cd_008', 'crime_detection', 'Organized Crime Investigation', 'What is the term for money obtained through illegal activities?', '["Dirty money", "Clean money", "Legal tender", "Foreign currency"]'::jsonb, 0, 'easy', 'Money obtained through illegal activities is referred to as "dirty money" and requires laundering.'),
('cd_009', 'crime_detection', 'Accident Investigation', 'What is the leading cause of vehicular accidents?', '["Human error", "Mechanical failure", "Road conditions", "Weather"]'::jsonb, 0, 'easy', 'Human error accounts for approximately 90% of all vehicular accidents.'),
('cd_010', 'crime_detection', 'Fundamentals of Criminal Investigation', 'What is the cardinal rule of crime scene investigation?', '["Do not touch anything", "Take photos first", "Interview witnesses", "Call for backup"]'::jsonb, 0, 'medium', 'The cardinal rule is to not touch, move, or alter anything at the crime scene until properly documented.'),
('cd_011', 'crime_detection', 'Crime Scene Investigation', 'What is the chain of custody?', '["Documentation of evidence handling", "Police hierarchy", "Court procedure", "Witness list"]'::jsonb, 0, 'medium', 'Chain of custody is the chronological documentation showing the seizure, custody, control, and disposition of evidence.'),
('cd_012', 'crime_detection', 'Crime Scene Investigation', 'What is physical evidence?', '["Tangible objects found at crime scene", "Witness testimony", "Confession", "Opinion"]'::jsonb, 0, 'easy', 'Physical evidence consists of tangible objects that can be collected and examined.'),
('cd_013', 'crime_detection', 'Crime Scene Investigation', 'What is testimonial evidence?', '["Statements made by witnesses", "Physical objects", "Documents", "Photographs"]'::jsonb, 0, 'easy', 'Testimonial evidence consists of statements made under oath by witnesses.'),
('cd_014', 'crime_detection', 'Crime Scene Investigation', 'What is the spiral search pattern?', '["Searching from center outward in circles", "Straight line search", "Grid search", "Random search"]'::jsonb, 0, 'medium', 'Spiral search moves from the center of the scene outward in ever-widening circles.'),
('cd_015', 'crime_detection', 'Crime Scene Investigation', 'What is the grid search pattern?', '["Overlapping strip searches at right angles", "Circular search", "Random search", "Zone search"]'::jsonb, 0, 'medium', 'Grid search involves two strip searches of the same area at right angles.'),
('cd_016', 'crime_detection', 'Fundamentals of Criminal Investigation', 'What is an interview in investigation?', '["Non-accusatory questioning of witness", "Accusatory questioning", "Arrest procedure", "Court testimony"]'::jsonb, 0, 'easy', 'An interview is non-accusatory questioning of witnesses or victims to gather information.'),
('cd_017', 'crime_detection', 'Fundamentals of Criminal Investigation', 'What is an interrogation?', '["Accusatory questioning of suspect", "Non-accusatory questioning", "Court testimony", "Evidence collection"]'::jsonb, 0, 'easy', 'Interrogation is accusatory questioning of a suspect to obtain a confession or admission.'),
('cd_018', 'crime_detection', 'Fundamentals of Criminal Investigation', 'What is modus operandi?', '["Method of operation used by criminal", "Motive for crime", "Type of weapon", "Time of crime"]'::jsonb, 0, 'medium', 'Modus operandi (MO) is the particular method or pattern used by a criminal in committing crimes.'),
('cd_019', 'crime_detection', 'Fundamentals of Criminal Investigation', 'What is a confession?', '["Admission of guilt by suspect", "Witness statement", "Expert opinion", "Physical evidence"]'::jsonb, 0, 'easy', 'A confession is a voluntary statement by a suspect admitting to committing a crime.'),
('cd_020', 'crime_detection', 'Fundamentals of Criminal Investigation', 'What is an admission?', '["Statement of fact tending to prove guilt", "Full confession", "Denial", "Alibi"]'::jsonb, 0, 'medium', 'An admission is a statement of fact that tends to prove guilt but is not a full confession.')
INSERT INTO questions (id, subject, topic, question_text, options, correct_answer_index, difficulty, explanation) VALUES
('cd_021', 'crime_detection', 'Drug Education and Vice Control', 'What is RA 9165?', '["Comprehensive Dangerous Drugs Act of 2002", "Anti-Money Laundering Act", "Firearms Act", "Anti-Trafficking Act"]'::jsonb, 0, 'medium', 'RA 9165 is the Comprehensive Dangerous Drugs Act of 2002.'),
('cd_022', 'crime_detection', 'Drug Education and Vice Control', 'What agency leads the anti-drug campaign in the Philippines?', '["PDEA", "PNP", "NBI", "DILG"]'::jsonb, 0, 'easy', 'PDEA (Philippine Drug Enforcement Agency) is the lead agency for anti-drug operations.'),
('cd_023', 'crime_detection', 'Drug Education and Vice Control', 'What is drug trafficking?', '["Illegal sale and distribution of drugs", "Drug use", "Drug treatment", "Drug testing"]'::jsonb, 0, 'easy', 'Drug trafficking is the illegal sale, transport, and distribution of controlled substances.'),
('cd_024', 'crime_detection', 'Drug Education and Vice Control', 'What is a buy-bust operation?', '["Undercover drug purchase and arrest", "Checkpoint operation", "Raid operation", "Surveillance operation"]'::jsonb, 0, 'easy', 'A buy-bust operation involves undercover purchase of drugs followed by immediate arrest.'),
('cd_025', 'crime_detection', 'Fire Technology', 'What is the fire tetrahedron?', '["Heat, Fuel, Oxygen, Chemical chain reaction", "Only heat and fuel", "Only oxygen", "Fire triangle"]'::jsonb, 0, 'medium', 'The fire tetrahedron adds chemical chain reaction to the fire triangle elements.'),
('cd_026', 'crime_detection', 'Fire Technology', 'What is the point of origin in fire investigation?', '["Location where fire started", "Exit point", "Hottest point", "Last point to burn"]'::jsonb, 0, 'easy', 'The point of origin is the location where the fire started.'),
('cd_027', 'crime_detection', 'Fire Technology', 'What is an accelerant?', '["Substance used to start or spread fire", "Fire extinguisher", "Fire retardant", "Water"]'::jsonb, 0, 'medium', 'An accelerant is a substance like gasoline used to start or accelerate the spread of fire.'),
('cd_028', 'crime_detection', 'Arson Investigation', 'What are the elements of arson?', '["Willful burning and criminal intent", "Accidental fire", "Natural fire", "Electrical fire"]'::jsonb, 0, 'medium', 'Arson requires willful or malicious burning with criminal intent.'),
('cd_029', 'crime_detection', 'Traffic Management', 'What are the 3 Es of traffic management?', '["Engineering, Education, Enforcement", "Entry, Exit, Emergency", "Evaluate, Execute, Enforce", "Examine, Explain, Execute"]'::jsonb, 0, 'medium', 'The 3 Es are Engineering (road design), Education (driver training), and Enforcement (traffic laws).'),
('cd_030', 'crime_detection', 'Traffic Management', 'What is traffic engineering?', '["Design of roads and traffic systems", "Driver education", "Law enforcement", "Vehicle inspection"]'::jsonb, 0, 'easy', 'Traffic engineering involves the design of roads, signals, and traffic control systems.'),
('cd_031', 'crime_detection', 'Traffic Management', 'What is a hit and run?', '["Leaving accident scene without identifying self", "Speeding violation", "Parking violation", "Red light violation"]'::jsonb, 0, 'easy', 'Hit and run is leaving an accident scene without providing identification or assistance.'),
('cd_032', 'crime_detection', 'Special Crime Investigation', 'What is human trafficking?', '["Illegal trade of humans for exploitation", "Immigration violation", "Smuggling goods", "Drug trafficking"]'::jsonb, 0, 'easy', 'Human trafficking is the illegal trade of humans for forced labor, sexual exploitation, or other purposes.'),
('cd_033', 'crime_detection', 'Special Crime Investigation', 'What is RA 9208?', '["Anti-Trafficking in Persons Act", "Anti-Drug Act", "Firearms Act", "Anti-Money Laundering Act"]'::jsonb, 0, 'hard', 'RA 9208 is the Anti-Trafficking in Persons Act of 2003.'),
('cd_034', 'crime_detection', 'Special Crime Investigation', 'What is cybercrime?', '["Crime committed using computers or internet", "Street crime", "Property crime", "Violent crime"]'::jsonb, 0, 'easy', 'Cybercrime is criminal activity involving computers, networks, or the internet.'),
('cd_035', 'crime_detection', 'Special Crime Investigation', 'What is RA 10175?', '["Cybercrime Prevention Act", "Anti-Drug Act", "Firearms Act", "Anti-Trafficking Act"]'::jsonb, 0, 'hard', 'RA 10175 is the Cybercrime Prevention Act of 2012.'),
('cd_036', 'crime_detection', 'Organized Crime Investigation', 'What is money laundering?', '["Making illegal money appear legal", "Counterfeiting", "Tax evasion", "Robbery"]'::jsonb, 0, 'easy', 'Money laundering is the process of making illegally obtained money appear legitimate.'),
('cd_037', 'crime_detection', 'Organized Crime Investigation', 'What is RA 9160?', '["Anti-Money Laundering Act", "Anti-Drug Act", "Firearms Act", "Cybercrime Act"]'::jsonb, 0, 'hard', 'RA 9160 is the Anti-Money Laundering Act of 2001.'),
('cd_038', 'crime_detection', 'Organized Crime Investigation', 'What is a syndicate?', '["Organized group engaged in criminal activity", "Solo criminal", "Witness", "Informant"]'::jsonb, 0, 'easy', 'A syndicate is an organized group that engages in criminal activities.'),
('cd_039', 'crime_detection', 'Accident Investigation', 'What is a traffic accident report?', '["Official documentation of vehicle accident", "Traffic ticket", "Court order", "Insurance claim"]'::jsonb, 0, 'easy', 'A traffic accident report is the official documentation of a vehicular accident.'),
('cd_040', 'crime_detection', 'Accident Investigation', 'What are skid marks used for in accident investigation?', '["Determine vehicle speed and direction", "Identify vehicle", "Find witnesses", "Determine fault"]'::jsonb, 0, 'medium', 'Skid marks help investigators determine vehicle speed and direction before impact.'),
('se_001', 'criminology', 'Introduction to Criminology', 'Who is known as the Father of Modern Criminology?', '["Cesare Lombroso", "Cesare Beccaria", "Enrico Ferri", "Raffaele Garofalo"]'::jsonb, 0, 'medium', 'Cesare Lombroso is known as the Father of Modern Criminology for his scientific approach to studying criminals.'),
('se_002', 'criminology', 'Psychology of Crimes', 'What theory suggests that criminal behavior is learned?', '["Differential Association Theory", "Strain Theory", "Labeling Theory", "Control Theory"]'::jsonb, 0, 'medium', 'Sutherland''s Differential Association Theory states that criminal behavior is learned through interaction with others.'),
('se_003', 'criminology', 'Philippine Criminal Justice System', 'What are the 5 pillars of the Philippine Criminal Justice System?', '["Law Enforcement, Prosecution, Courts, Corrections, Community", "Police, Lawyers, Judges, Prisons, Citizens", "PNP, DOJ, SC, BUCOR, Barangay", "Investigation, Trial, Verdict, Punishment, Rehabilitation"]'::jsonb, 0, 'medium', 'The 5 pillars are: Law Enforcement, Prosecution, Courts, Corrections, and Community.'),
('se_004', 'criminology', 'Ethics and Values', 'What is police ethics?', '["Moral principles guiding police conduct", "Police regulations", "Criminal laws", "Police training"]'::jsonb, 0, 'easy', 'Police ethics refers to the moral principles and values that guide the conduct of law enforcement officers.'),
('se_005', 'criminology', 'Juvenile Delinquency', 'What is a juvenile delinquent?', '["A minor who commits a crime", "An adult criminal", "A repeat offender", "A first-time offender"]'::jsonb, 0, 'easy', 'A juvenile delinquent is a minor (person below 18) who commits an act that would be a crime if committed by an adult.'),
('se_006', 'criminology', 'Human Behavior', 'What is deviant behavior?', '["Behavior that violates social norms", "Normal behavior", "Legal behavior", "Moral behavior"]'::jsonb, 0, 'easy', 'Deviant behavior is any behavior that violates social norms and expectations.'),
('se_007', 'criminology', 'Crisis Management', 'What is the first step in crisis management?', '["Identify the crisis", "Call the media", "Evacuate", "Wait for instructions"]'::jsonb, 0, 'easy', 'The first step in crisis management is to identify and assess the nature and scope of the crisis.'),
('se_008', 'criminology', 'Introduction to Criminology', 'What is the Classical School of Criminology''s main principle?', '["Free will and rational choice", "Biological determinism", "Social environment", "Economic factors"]'::jsonb, 0, 'medium', 'The Classical School believes that people have free will and make rational choices to commit crimes.'),
('se_009', 'criminology', 'Criminological Research', 'What is the purpose of criminological research?', '["Understand causes of crime", "Punish criminals", "Create new laws", "Train police officers"]'::jsonb, 0, 'easy', 'Criminological research aims to understand the causes, nature, and prevention of criminal behavior.'),
('se_010', 'criminology', 'Statistics', 'What is crime rate?', '["Number of crimes per population", "Total number of crimes", "Number of arrests", "Number of convictions"]'::jsonb, 0, 'easy', 'Crime rate is the number of crimes per unit of population, usually expressed per 100,000 people.'),
('se_011', 'criminology', 'Introduction to Criminology', 'Who is the Father of Classical Criminology?', '["Cesare Beccaria", "Cesare Lombroso", "Enrico Ferri", "Raffaele Garofalo"]'::jsonb, 0, 'medium', 'Cesare Beccaria is the Father of Classical Criminology for his work "On Crimes and Punishments."'),
('se_012', 'criminology', 'Introduction to Criminology', 'What is the Positivist School of Criminology?', '["Crime is caused by factors beyond free will", "Crime is a rational choice", "Crime is purely random", "Crime is always intentional"]'::jsonb, 0, 'medium', 'The Positivist School believes crime is caused by biological, psychological, or social factors beyond free will.'),
('se_013', 'criminology', 'Introduction to Criminology', 'What is Lombroso''s theory of the "born criminal"?', '["Some people are born with criminal traits", "All criminals learn crime", "Crime is a choice", "Environment causes crime"]'::jsonb, 0, 'medium', 'Lombroso believed some individuals are born with atavistic traits predisposing them to crime.'),
('se_014', 'criminology', 'Psychology of Crimes', 'What is Strain Theory?', '["Crime results from gap between goals and means", "Crime is learned behavior", "Crime is biological", "Crime is random"]'::jsonb, 0, 'hard', 'Merton''s Strain Theory states crime results from the gap between cultural goals and legitimate means.'),
('se_015', 'criminology', 'Psychology of Crimes', 'What is Labeling Theory?', '["Being labeled criminal leads to more crime", "Labels prevent crime", "Crime is biological", "Crime is rational"]'::jsonb, 0, 'medium', 'Labeling Theory suggests that being labeled as a criminal can lead to further criminal behavior.'),
('se_016', 'criminology', 'Psychology of Crimes', 'What is Social Control Theory?', '["Strong social bonds prevent crime", "Weak bonds cause crime", "Labels cause crime", "Biology causes crime"]'::jsonb, 0, 'medium', 'Hirschi''s Social Control Theory states strong social bonds to family, school, and community prevent crime.'),
('se_017', 'criminology', 'Psychology of Crimes', 'What is Social Learning Theory?', '["Crime is learned through observation", "Crime is inherited", "Crime is random", "Crime is always rational"]'::jsonb, 0, 'medium', 'Social Learning Theory states criminal behavior is learned through observation and imitation.'),
('se_018', 'criminology', 'Psychology of Crimes', 'What is Routine Activities Theory?', '["Crime occurs when target, offender, and no guardian meet", "Crime is biological", "Crime is learned", "Crime is random"]'::jsonb, 0, 'hard', 'Routine Activities Theory requires convergence of motivated offender, suitable target, and absence of guardian.'),
('se_019', 'criminology', 'Philippine Criminal Justice System', 'Which pillar represents the police?', '["Law Enforcement", "Prosecution", "Courts", "Corrections"]'::jsonb, 0, 'easy', 'Law Enforcement pillar includes the PNP and other agencies responsible for apprehending offenders.'),
('se_020', 'criminology', 'Philippine Criminal Justice System', 'Which pillar represents the courts?', '["Judiciary", "Law Enforcement", "Prosecution", "Corrections"]'::jsonb, 0, 'easy', 'The Judiciary pillar includes courts that try cases and render judgment.'),
('se_021', 'criminology', 'Philippine Criminal Justice System', 'What agency represents the Prosecution pillar?', '["Department of Justice", "Supreme Court", "PNP", "BUCOR"]'::jsonb, 0, 'easy', 'The Department of Justice and its prosecutors represent the Prosecution pillar.'),
('se_022', 'criminology', 'Philippine Criminal Justice System', 'What is the Community pillar?', '["Public participation in crime prevention", "Police community", "Court community", "Prison community"]'::jsonb, 0, 'easy', 'The Community pillar involves citizen participation in crime prevention and rehabilitation.'),
('se_023', 'criminology', 'Ethics and Values', 'What is professional ethics?', '["Standards of conduct in a profession", "Personal beliefs", "Religious rules", "Political views"]'::jsonb, 0, 'easy', 'Professional ethics are the standards of conduct and moral principles in a specific profession.'),
('se_024', 'criminology', 'Ethics and Values', 'What is integrity in law enforcement?', '["Honesty and adherence to moral principles", "Physical strength", "Intelligence", "Popularity"]'::jsonb, 0, 'easy', 'Integrity means being honest and adhering to moral and ethical principles.'),
('se_025', 'criminology', 'Ethics and Values', 'What is police corruption?', '["Misuse of authority for personal gain", "Hard work", "Following rules", "Community service"]'::jsonb, 0, 'easy', 'Police corruption is the misuse of police authority for personal or organizational gain.'),
('se_026', 'criminology', 'Juvenile Delinquency', 'What is RA 9344?', '["Juvenile Justice and Welfare Act", "Anti-Drug Act", "Firearms Act", "Anti-Trafficking Act"]'::jsonb, 0, 'medium', 'RA 9344 is the Juvenile Justice and Welfare Act of 2006.'),
('se_027', 'criminology', 'Juvenile Delinquency', 'What is the minimum age of criminal responsibility?', '["15 years old", "12 years old", "18 years old", "9 years old"]'::jsonb, 0, 'medium', 'Under RA 9344, the minimum age of criminal responsibility is 15 years old.'),
('se_028', 'criminology', 'Juvenile Delinquency', 'What is diversion in juvenile justice?', '["Alternative to formal court proceedings", "Prison sentence", "Death penalty", "Life imprisonment"]'::jsonb, 0, 'medium', 'Diversion refers to alternatives to formal prosecution for juvenile offenders.'),
('se_029', 'criminology', 'Human Behavior', 'What is recidivism?', '["Repeated criminal behavior after punishment", "First offense", "Accidental crime", "Self-defense"]'::jsonb, 0, 'easy', 'Recidivism is the tendency of a convicted criminal to reoffend.'),
('se_030', 'criminology', 'Human Behavior', 'What is victimology?', '["Study of crime victims", "Study of criminals", "Study of punishment", "Study of police"]'::jsonb, 0, 'easy', 'Victimology is the scientific study of victims and their relationship to crime.'),
('se_031', 'criminology', 'Human Behavior', 'What is white-collar crime?', '["Non-violent crime for financial gain by professionals", "Street crime", "Violent crime", "Drug crime"]'::jsonb, 0, 'easy', 'White-collar crime is non-violent crime committed by business or government professionals for financial gain.'),
('se_032', 'criminology', 'Human Behavior', 'What is organized crime?', '["Criminal activities by structured groups", "Individual crime", "Accidental crime", "Petty crime"]'::jsonb, 0, 'easy', 'Organized crime involves criminal activities carried out by structured criminal organizations.'),
('se_033', 'criminology', 'Introduction to Criminology', 'What is penology?', '["Study of punishment and prison management", "Study of crime", "Study of victims", "Study of police"]'::jsonb, 0, 'easy', 'Penology is the study of punishment, prison management, and rehabilitation of offenders.'),
('se_034', 'criminology', 'Introduction to Criminology', 'What is etiology of crime?', '["Study of causes of crime", "Study of punishment", "Study of victims", "Study of laws"]'::jsonb, 0, 'medium', 'Etiology of crime refers to the study of the causes and origins of criminal behavior.'),
('se_035', 'criminology', 'Psychology of Crimes', 'What is psychopathy?', '["Personality disorder with lack of empathy", "Normal personality", "High intelligence", "Depression"]'::jsonb, 0, 'medium', 'Psychopathy is a personality disorder characterized by lack of empathy, manipulative behavior, and antisocial conduct.'),
('se_036', 'criminology', 'Psychology of Crimes', 'What is sociopathy?', '["Antisocial personality developed through environment", "Biological condition", "Intelligence level", "Physical trait"]'::jsonb, 0, 'medium', 'Sociopathy is an antisocial personality believed to develop through environmental factors.'),
('se_037', 'criminology', 'Crisis Management', 'What is hostage negotiation?', '["Communication to secure release of hostages", "Armed assault", "Retreat", "Media conference"]'::jsonb, 0, 'easy', 'Hostage negotiation involves communication with hostage-takers to secure peaceful release.'),
('se_038', 'criminology', 'Crisis Management', 'What is the Stockholm Syndrome?', '["Hostages develop positive feelings for captors", "Fear of captors", "Escape attempt", "Resistance"]'::jsonb, 0, 'medium', 'Stockholm Syndrome occurs when hostages develop emotional bonds with their captors.'),
('se_039', 'criminology', 'Statistics', 'What is crime index?', '["Measure of serious crimes reported", "Total crimes", "Petty crimes only", "Traffic violations"]'::jsonb, 0, 'medium', 'Crime index measures the incidence of serious crimes like murder, rape, robbery, and theft.'),
('se_040', 'criminology', 'Statistics', 'What is crime volume?', '["Total number of crimes committed", "Crime rate", "Crime index", "Clearance rate"]'::jsonb, 0, 'easy', 'Crime volume is the total number of crimes committed in a given area and time.'),
('ca_001', 'corrections', 'Institutional Corrections', 'What is the purpose of imprisonment?', '["Punishment and rehabilitation", "Revenge only", "Entertainment", "Profit"]'::jsonb, 0, 'easy', 'Imprisonment serves both as punishment for crimes and as an opportunity for rehabilitation.'),
('ca_002', 'corrections', 'Non-Institutional Corrections', 'What is probation?', '["Community-based supervision instead of prison", "Early release from prison", "Presidential pardon", "House arrest"]'::jsonb, 0, 'easy', 'Probation is a court-ordered period of supervision in the community as an alternative to imprisonment.'),
('ca_003', 'corrections', 'Parole', 'What is parole?', '["Conditional release from prison before full sentence", "Permanent release", "Transfer to another prison", "Death row clemency"]'::jsonb, 0, 'easy', 'Parole is the conditional release of a prisoner before completing their full sentence.'),
('ca_004', 'corrections', 'Rehabilitation Programs', 'What is the main goal of rehabilitation?', '["Reform offenders to prevent reoffending", "Punish severely", "Isolate from society", "Generate labor"]'::jsonb, 0, 'easy', 'Rehabilitation aims to reform offenders and help them reintegrate into society as law-abiding citizens.'),
('ca_005', 'corrections', 'Inmate Classification', 'Why are inmates classified?', '["For security and program placement", "For punishment levels", "For food preferences", "For visiting schedules"]'::jsonb, 0, 'easy', 'Inmates are classified based on security risk and needs for appropriate placement and programming.'),
('ca_006', 'corrections', 'Prison Security', 'What is maximum security prison for?', '["Most dangerous inmates", "First-time offenders", "Minor offenders", "Juvenile offenders"]'::jsonb, 0, 'easy', 'Maximum security prisons house the most dangerous criminals who pose the highest escape or violence risk.'),
('ca_007', 'corrections', 'Therapeutic Communities', 'What is a therapeutic community in corrections?', '["Treatment-based residential program", "Regular prison wing", "Solitary confinement", "Work release program"]'::jsonb, 0, 'medium', 'A therapeutic community is a residential treatment program focusing on substance abuse and behavioral change.'),
('ca_008', 'corrections', 'Institutional Corrections', 'What agency manages national prisons in the Philippines?', '["Bureau of Corrections (BUCOR)", "BJMP", "PNP", "NBI"]'::jsonb, 0, 'easy', 'The Bureau of Corrections (BUCOR) manages national penitentiaries for those sentenced to more than 3 years.'),
('ca_009', 'corrections', 'Non-Institutional Corrections', 'What agency supervises probationers in the Philippines?', '["Parole and Probation Administration", "BUCOR", "BJMP", "DSWD"]'::jsonb, 0, 'medium', 'The Parole and Probation Administration supervises probationers and parolees in the community.'),
('ca_010', 'corrections', 'Pardon and Amnesty', 'Who has the power to grant pardon in the Philippines?', '["The President", "The Supreme Court", "The Congress", "The DILG Secretary"]'::jsonb, 0, 'easy', 'The President of the Philippines has the power to grant pardons, reprieves, and amnesty.'),
('ca_011', 'corrections', 'Institutional Corrections', 'What is BJMP?', '["Bureau of Jail Management and Penology", "Bureau of Justice Management", "Bureau of Juvenile Management", "Bureau of Judicial Process"]'::jsonb, 0, 'easy', 'BJMP manages city, district, and municipal jails for those awaiting trial or serving sentences of 3 years or less.'),
('ca_012', 'corrections', 'Institutional Corrections', 'What is the difference between jail and prison?', '["Jail for short-term, prison for long-term", "Same thing", "Jail is larger", "Prison is for women only"]'::jsonb, 0, 'easy', 'Jails hold those awaiting trial or short sentences; prisons hold those with longer sentences.'),
('ca_013', 'corrections', 'Institutional Corrections', 'What is the New Bilibid Prison?', '["National penitentiary in Muntinlupa", "Provincial jail", "City jail", "Juvenile facility"]'::jsonb, 0, 'easy', 'New Bilibid Prison is the national penitentiary located in Muntinlupa City.'),
('ca_014', 'corrections', 'Institutional Corrections', 'What is medium security prison for?', '["Inmates with moderate escape risk", "Most dangerous inmates", "First-time offenders only", "Juveniles only"]'::jsonb, 0, 'easy', 'Medium security prisons house inmates with moderate security risks.'),
('ca_015', 'corrections', 'Institutional Corrections', 'What is minimum security prison for?', '["Low-risk inmates nearing release", "Most dangerous inmates", "High-risk inmates", "Death row inmates"]'::jsonb, 0, 'easy', 'Minimum security prisons house low-risk inmates, often those nearing release.'),
('ca_016', 'corrections', 'Non-Institutional Corrections', 'What is PD 968?', '["Probation Law of 1976", "Prison Law", "Parole Law", "Amnesty Law"]'::jsonb, 0, 'hard', 'PD 968 is the Probation Law of 1976, establishing the probation system in the Philippines.'),
('ca_017', 'corrections', 'Non-Institutional Corrections', 'Who can grant probation?', '["The trial court", "The President", "The PNP", "The BJMP"]'::jsonb, 0, 'medium', 'The trial court that convicted the offender has the power to grant probation.'),
('ca_018', 'corrections', 'Non-Institutional Corrections', 'What crimes are not eligible for probation?', '["Those sentenced to more than 6 years", "All crimes", "Minor crimes only", "First offenses"]'::jsonb, 0, 'medium', 'Offenders sentenced to more than 6 years imprisonment are not eligible for probation.'),
('ca_019', 'corrections', 'Parole', 'What is the Indeterminate Sentence Law?', '["Law providing minimum and maximum sentence", "Fixed sentence law", "Death penalty law", "Probation law"]'::jsonb, 0, 'hard', 'The Indeterminate Sentence Law requires courts to impose minimum and maximum terms.'),
('ca_020', 'corrections', 'Parole', 'Who grants parole?', '["Board of Pardons and Parole", "Trial court", "President", "Supreme Court"]'::jsonb, 0, 'medium', 'The Board of Pardons and Parole grants parole to qualified prisoners.'),
('ca_021', 'corrections', 'Pardon and Amnesty', 'What is the difference between pardon and amnesty?', '["Pardon is individual, amnesty is for groups", "Same thing", "Amnesty is individual", "Pardon requires conviction"]'::jsonb, 0, 'medium', 'Pardon is granted to individuals after conviction; amnesty is for groups, often political offenders.'),
('ca_022', 'corrections', 'Pardon and Amnesty', 'What is commutation?', '["Reduction of sentence", "Full pardon", "Amnesty", "Probation"]'::jsonb, 0, 'medium', 'Commutation is the reduction of a sentence to a lesser penalty.'),
('ca_023', 'corrections', 'Pardon and Amnesty', 'What is reprieve?', '["Temporary postponement of sentence", "Full pardon", "Reduced sentence", "Probation"]'::jsonb, 0, 'medium', 'Reprieve is a temporary postponement or suspension of the execution of a sentence.'),
('ca_024', 'corrections', 'Rehabilitation Programs', 'What is Good Conduct Time Allowance (GCTA)?', '["Time deduction for good behavior", "Time added for bad behavior", "Parole period", "Probation period"]'::jsonb, 0, 'medium', 'GCTA is time credited to inmates for good conduct, reducing their prison stay.'),
('ca_025', 'corrections', 'Rehabilitation Programs', 'What are livelihood programs in prison?', '["Skills training for inmates", "Punishment programs", "Security programs", "Guard training"]'::jsonb, 0, 'easy', 'Livelihood programs teach inmates skills for employment after release.'),
('ca_026', 'corrections', 'Rehabilitation Programs', 'What is restorative justice?', '["Repairing harm through offender-victim reconciliation", "Maximum punishment", "Revenge", "Isolation"]'::jsonb, 0, 'medium', 'Restorative justice focuses on repairing harm through cooperation between offenders and victims.'),
('ca_027', 'corrections', 'Inmate Classification', 'What is the purpose of reception and diagnostic center?', '["Assess and classify new inmates", "Release inmates", "Execute sentences", "Train guards"]'::jsonb, 0, 'medium', 'Reception and diagnostic centers assess new inmates for proper classification and placement.'),
('ca_028', 'corrections', 'Inmate Classification', 'What factors are considered in inmate classification?', '["Crime, sentence, behavior, security risk", "Height only", "Weight only", "Age only"]'::jsonb, 0, 'medium', 'Classification considers crime committed, length of sentence, behavior, and security risk.'),
('ca_029', 'corrections', 'Prison Security', 'What is contraband in prison?', '["Prohibited items inside prison", "Legal items", "Food items", "Clothing"]'::jsonb, 0, 'easy', 'Contraband refers to items prohibited inside prison, such as weapons, drugs, and phones.'),
('ca_030', 'corrections', 'Prison Security', 'What is solitary confinement?', '["Isolation of inmate from others", "Group housing", "Work release", "Parole"]'::jsonb, 0, 'easy', 'Solitary confinement isolates an inmate from the general prison population.'),
('cj_061', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is the territorial principle in criminal law?', '["Laws apply within Philippine territory", "Laws apply worldwide", "Laws apply to Filipinos only", "Laws apply to foreigners only"]'::jsonb, 0, 'easy', 'The territorial principle means penal laws are enforceable within Philippine territory.'),
('cj_062', 'criminal_jurisprudence', 'Criminal Law Book I', 'What does "nullum crimen, nulla poena sine lege" mean?', '["No crime without law", "No punishment without trial", "No arrest without warrant", "No bail for serious crimes"]'::jsonb, 0, 'easy', 'This Latin maxim means there is no crime when there is no law punishing it.'),
('cj_063', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is criminal intent?', '["The purpose to commit a crime", "Accidental commission", "Negligent act", "Self-defense"]'::jsonb, 0, 'easy', 'Criminal intent is the deliberate purpose to commit a criminal act.'),
('cj_064', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is a felony?', '["Act punishable by the RPC", "Civil wrong", "Administrative offense", "Moral wrong"]'::jsonb, 0, 'easy', 'A felony is an act or omission punishable by the Revised Penal Code.'),
('cj_065', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is an offense?', '["Act punishable by special laws", "Act punishable by RPC only", "Civil liability", "Moral wrong"]'::jsonb, 0, 'easy', 'An offense is a violation of special penal laws outside the RPC.'),
('cj_066', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is the effect of repeal of a penal law?', '["Generally favorable to the accused", "Always unfavorable", "No effect", "Increases penalty"]'::jsonb, 0, 'easy', 'Repeal of a penal law generally benefits the accused unless otherwise provided.'),
('cj_067', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is physical injury?', '["Harm to body of a person", "Damage to property", "Theft", "Fraud"]'::jsonb, 0, 'easy', 'Physical injury refers to bodily harm inflicted on another person.'),
('cj_068', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is grave coercion?', '["Compelling someone by violence", "Peaceful persuasion", "Written request", "Legal order"]'::jsonb, 0, 'easy', 'Grave coercion is compelling another to do something against their will through violence.'),
('cj_069', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is trespass to dwelling?', '["Entering home without consent", "Legal entry", "Authorized search", "Invited guest"]'::jsonb, 0, 'easy', 'Trespass to dwelling is entering another''s home without permission.'),
('cj_070', 'criminal_jurisprudence', 'Criminal Procedure', 'What is a subpoena?', '["Court order to appear or produce documents", "Arrest warrant", "Search warrant", "Bail bond"]'::jsonb, 0, 'easy', 'A subpoena is a court order requiring a person to appear in court or produce documents.')
INSERT INTO questions (id, subject, topic, question_text, options, correct_answer_index, difficulty, explanation) VALUES
('cj_071', 'criminal_jurisprudence', 'Criminal Procedure', 'What is jurisdiction in criminal cases?', '["Power of court to hear a case", "Location of crime", "Identity of accused", "Type of punishment"]'::jsonb, 0, 'easy', 'Jurisdiction is the authority of a court to hear and decide a criminal case.'),
('cj_072', 'criminal_jurisprudence', 'Criminal Procedure', 'What is venue in criminal procedure?', '["Place where case is tried", "Time of trial", "Judge assigned", "Prosecutor assigned"]'::jsonb, 0, 'easy', 'Venue refers to the geographic location where a criminal case is tried.'),
('cj_073', 'criminal_jurisprudence', 'Rules of Evidence', 'What is direct evidence?', '["Evidence proving fact without inference", "Circumstantial evidence", "Opinion evidence", "Hearsay"]'::jsonb, 0, 'easy', 'Direct evidence proves a fact directly without need for inference.'),
('cj_074', 'criminal_jurisprudence', 'Rules of Evidence', 'What is circumstantial evidence?', '["Evidence requiring inference", "Direct testimony", "Documentary evidence", "Physical evidence"]'::jsonb, 0, 'easy', 'Circumstantial evidence requires inference to connect it to the fact in issue.'),
('cj_075', 'criminal_jurisprudence', 'Rules of Evidence', 'What is testimonial evidence?', '["Evidence given orally by witness", "Written documents", "Physical objects", "Photographs"]'::jsonb, 0, 'easy', 'Testimonial evidence is oral testimony given by a witness in court.'),
('cj_076', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is the doctrine of pro reo?', '["Doubt resolved in favor of accused", "Strict interpretation against accused", "No presumption of innocence", "Burden on accused"]'::jsonb, 0, 'hard', 'Pro reo means all doubts should be resolved in favor of the accused.'),
('cj_077', 'criminal_jurisprudence', 'Criminal Law Book I', 'What are the stages of commission of a felony?', '["Consummated, frustrated, attempted", "Planning, execution, completion", "Intent, act, result", "Preparation, overt act, completion"]'::jsonb, 0, 'hard', 'Felonies may be consummated, frustrated, or attempted depending on stage of execution.'),
('cj_078', 'criminal_jurisprudence', 'Criminal Law Book I', 'When is a felony frustrated?', '["All acts done but result not produced", "Crime is complete", "Only some acts done", "No act performed"]'::jsonb, 0, 'hard', 'A frustrated felony occurs when all acts are performed but the felony is not produced by causes independent of the will of the perpetrator.'),
('cj_079', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is the complex crime of rebellion with murder?', '["Murder absorbed in rebellion", "Separate crimes", "Only murder punished", "Only rebellion punished"]'::jsonb, 0, 'hard', 'Common crimes like murder committed in furtherance of rebellion are absorbed in the crime of rebellion.'),
('cj_080', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is the indeterminate sentence law?', '["Minimum and maximum sentence imposed", "Fixed sentence only", "No sentence", "Probation only"]'::jsonb, 0, 'hard', 'The ISL requires courts to impose a minimum and maximum term of imprisonment.'),
('cj_081', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is the three-fold rule in service of sentence?', '["Maximum 40 years even if total exceeds", "Serve all sentences fully", "Concurrent service", "No maximum"]'::jsonb, 0, 'hard', 'Under the three-fold rule, the maximum duration is not more than three times the most severe penalty but shall not exceed 40 years.'),
('cj_082', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is the effect of absolutory cause?', '["Act is wrong but offender exempt", "Act is not wrong", "Heavier penalty", "No exemption"]'::jsonb, 0, 'hard', 'Absolutory causes exempt the actor from punishment although the act is a crime.'),
('cj_083', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is an impossible crime?', '["Act would be crime if not for inherent impossibility", "Completed crime", "No criminal liability", "Civil liability only"]'::jsonb, 0, 'hard', 'An impossible crime is committed when the act would be a crime but is inherently impossible of accomplishment.'),
('cj_084', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is the doctrine of absorption in robbery with homicide?', '["Other crimes absorbed in special complex crime", "Separate punishment for each", "Lighter penalty", "No absorption"]'::jsonb, 0, 'hard', 'In robbery with homicide, other crimes like rape committed on the occasion are absorbed.'),
('cj_085', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is plunder under RA 7080?', '["Accumulating ill-gotten wealth of at least P50 million", "Simple theft", "Estafa", "Robbery"]'::jsonb, 0, 'hard', 'Plunder is committed by a public officer who accumulates ill-gotten wealth of at least P50 million.'),
('lea_061', 'law_enforcement', 'Police Organization and Administration', 'What is the primary function of the police?', '["Maintain peace and order", "Collect taxes", "Build roads", "Teach in schools"]'::jsonb, 0, 'easy', 'The primary function of police is to maintain peace and order in the community.'),
('lea_062', 'law_enforcement', 'Police Organization and Administration', 'What does PNP stand for?', '["Philippine National Police", "Police National Program", "Philippine New Police", "Public National Police"]'::jsonb, 0, 'easy', 'PNP stands for Philippine National Police, the national police force.'),
('lea_063', 'law_enforcement', 'Police Organization and Administration', 'Who is the head of the PNP?', '["Chief PNP", "President", "Secretary of DILG", "Mayor"]'::jsonb, 0, 'easy', 'The Chief PNP is the head of the Philippine National Police.'),
('lea_064', 'law_enforcement', 'Police Organization and Administration', 'What is a police station?', '["Basic unit of PNP in a municipality", "National headquarters", "Regional office", "Provincial office"]'::jsonb, 0, 'easy', 'A police station is the basic unit of the PNP at the municipal or city level.'),
('lea_065', 'law_enforcement', 'Police Patrol Operations', 'What is foot patrol?', '["Walking patrol by police officers", "Vehicle patrol", "Helicopter patrol", "Boat patrol"]'::jsonb, 0, 'easy', 'Foot patrol involves police officers patrolling an area on foot.'),
('lea_066', 'law_enforcement', 'Police Patrol Operations', 'What is the purpose of patrol?', '["Crime prevention and detection", "Tax collection", "Traffic management only", "Building inspection"]'::jsonb, 0, 'easy', 'Patrol aims to prevent crime, detect criminal activity, and maintain public safety.'),
('lea_067', 'law_enforcement', 'Police Patrol Operations', 'What is mobile patrol?', '["Patrol using vehicles", "Foot patrol", "Stationary guard", "Undercover operation"]'::jsonb, 0, 'easy', 'Mobile patrol uses vehicles to cover larger areas more efficiently.'),
('lea_068', 'law_enforcement', 'Police Communication System', 'What is police radio communication?', '["Two-way radio for police use", "Television", "Newspaper", "Social media"]'::jsonb, 0, 'easy', 'Police radio communication uses two-way radios for official police communications.'),
('lea_069', 'law_enforcement', 'Police Communication System', 'What is the emergency hotline in the Philippines?', '["911", "123", "999", "112"]'::jsonb, 0, 'easy', '911 is the national emergency hotline in the Philippines.'),
('lea_070', 'law_enforcement', 'Police Intelligence', 'What is police intelligence?', '["Gathering information for law enforcement", "Building houses", "Teaching", "Farming"]'::jsonb, 0, 'easy', 'Police intelligence involves collecting and analyzing information for law enforcement.'),
('lea_071', 'law_enforcement', 'Police Intelligence', 'What is an informant?', '["Person who provides information to police", "Police officer", "Judge", "Prosecutor"]'::jsonb, 0, 'easy', 'An informant is someone who provides information to law enforcement.'),
('lea_072', 'law_enforcement', 'Police Personnel Management', 'What is the minimum age to join the PNP?', '["21 years old", "18 years old", "25 years old", "30 years old"]'::jsonb, 0, 'easy', 'The minimum age requirement to join the PNP is 21 years old.'),
('lea_073', 'law_enforcement', 'Police Personnel Management', 'What is the minimum height for male PNP applicants?', '["5''4\" or 162 cm", "5''0\" or 152 cm", "6''0\" or 183 cm", "5''8\" or 173 cm"]'::jsonb, 0, 'easy', 'Male PNP applicants must be at least 5''4" or 162 cm tall.'),
('lea_074', 'law_enforcement', 'Police Records Management', 'What is a police blotter?', '["Record of daily police activities", "Criminal record", "Court decision", "Law book"]'::jsonb, 0, 'easy', 'A police blotter is the official record of daily police station activities and incidents.'),
('lea_075', 'law_enforcement', 'Police Records Management', 'What is a rogues gallery?', '["Collection of criminal photographs", "Art gallery", "Police station", "Court room"]'::jsonb, 0, 'easy', 'A rogues gallery is a collection of photographs of known criminals for identification.'),
('lea_076', 'law_enforcement', 'Police Organization and Administration', 'What is the doctrine of command responsibility in police operations?', '["Superior responsible for subordinate acts", "No responsibility for subordinates", "Individual liability only", "Civil liability only"]'::jsonb, 0, 'hard', 'Command responsibility holds superiors accountable for the acts of their subordinates.'),
('lea_077', 'law_enforcement', 'Police Planning', 'What is SWOT analysis in police planning?', '["Strengths, Weaknesses, Opportunities, Threats", "Strategic Work On Targets", "Special Weapons Operations Team", "Standard Work Order Template"]'::jsonb, 0, 'hard', 'SWOT analysis evaluates Strengths, Weaknesses, Opportunities, and Threats for strategic planning.'),
('lea_078', 'law_enforcement', 'Police Planning', 'What is the SARA model in problem-oriented policing?', '["Scanning, Analysis, Response, Assessment", "Strategic Area Response Action", "Special Armed Response Action", "Standard Area Review Assessment"]'::jsonb, 0, 'hard', 'SARA stands for Scanning, Analysis, Response, and Assessment in problem-oriented policing.'),
('lea_079', 'law_enforcement', 'Industrial Security Administration', 'What is the primary objective of industrial security?', '["Protect assets and personnel", "Increase production", "Reduce taxes", "Marketing"]'::jsonb, 0, 'hard', 'Industrial security primarily aims to protect company assets and personnel from threats.'),
('lea_080', 'law_enforcement', 'Police Intelligence', 'What is the intelligence cycle?', '["Planning, Collection, Processing, Dissemination", "Investigation only", "Arrest only", "Prosecution only"]'::jsonb, 0, 'hard', 'The intelligence cycle consists of Planning, Collection, Processing, and Dissemination of information.'),
('lea_081', 'law_enforcement', 'Police Intelligence', 'What is HUMINT?', '["Human Intelligence", "Humanitarian Intelligence", "Humble Intelligence", "Humorous Intelligence"]'::jsonb, 0, 'hard', 'HUMINT refers to Human Intelligence - information gathered from human sources.'),
('lea_082', 'law_enforcement', 'Police Intelligence', 'What is SIGINT?', '["Signals Intelligence", "Signature Intelligence", "Sign Intelligence", "Simple Intelligence"]'::jsonb, 0, 'hard', 'SIGINT means Signals Intelligence - information gathered from intercepted signals.'),
('lea_083', 'law_enforcement', 'Comparative Police System', 'What type of police system does the Philippines have?', '["National police system", "Federal police system", "Municipal police only", "No police system"]'::jsonb, 0, 'hard', 'The Philippines has a national police system with the PNP as the sole police force.'),
('lea_084', 'law_enforcement', 'Comparative Police System', 'What is community-oriented policing?', '["Partnership between police and community", "Police acting alone", "Military policing", "Private security"]'::jsonb, 0, 'hard', 'Community-oriented policing emphasizes partnership between police and the community.'),
('lea_085', 'law_enforcement', 'Comparative Police System', 'What is the Peelian Principle?', '["Police are public and public are police", "Military control of police", "Separate police from public", "Foreign police system"]'::jsonb, 0, 'hard', 'Sir Robert Peel''s principle states that the police are the public and the public are the police.'),
('cr_061', 'criminalistics', 'Personal Identification', 'What is the most reliable means of identification?', '["Fingerprints", "Clothing", "Height", "Weight"]'::jsonb, 0, 'easy', 'Fingerprints are the most reliable means of identification because they are unique to each person.'),
('cr_062', 'criminalistics', 'Personal Identification', 'What are the three general fingerprint patterns?', '["Loop, Whorl, Arch", "Circle, Square, Triangle", "Line, Curve, Dot", "Ridge, Valley, Delta"]'::jsonb, 0, 'easy', 'The three general fingerprint patterns are Loop (60-65%), Whorl (30-35%), and Arch (5%).'),
('cr_063', 'criminalistics', 'Personal Identification', 'What is dactyloscopy?', '["Study of fingerprints", "Study of handwriting", "Study of bullets", "Study of blood"]'::jsonb, 0, 'easy', 'Dactyloscopy is the scientific study and classification of fingerprints.'),
('cr_064', 'criminalistics', 'Police Photography', 'What is crime scene photography?', '["Recording crime scene through photographs", "Studio photography", "Portrait photography", "Landscape photography"]'::jsonb, 0, 'easy', 'Crime scene photography documents the crime scene and evidence through photographs.'),
