('cr_069', 'criminalistics', 'Questioned Documents Examination', 'What is a questioned document?', '["Document with disputed authenticity", "Any legal document", "Government document", "Personal letter"]'::jsonb, 0, 'easy', 'A questioned document is one whose authenticity or origin is in dispute.'),
('cr_070', 'criminalistics', 'Questioned Documents Examination', 'What is handwriting analysis?', '["Examination of writing characteristics", "Reading documents", "Typing documents", "Printing documents"]'::jsonb, 0, 'easy', 'Handwriting analysis examines writing characteristics to identify the writer.'),
