('cr_075', 'criminalistics', 'DNA Analysis', 'What is DNA?', '["Genetic material in cells", "Type of blood", "Type of fingerprint", "Type of document"]'::jsonb, 0, 'easy', 'DNA (Deoxyribonucleic acid) is the genetic material found in cells that makes each person unique.'),
('cr_076', 'criminalistics', 'Personal Identification', 'What is the AFIS system?', '["Automated Fingerprint Identification System", "Automatic Fire Investigation System", "Armed Forces Intelligence System", "Audio Forensic Investigation System"]'::jsonb, 0, 'hard', 'AFIS is the Automated Fingerprint Identification System for computerized fingerprint matching.'),
('cr_077', 'criminalistics', 'Personal Identification', 'What are the types of fingerprint minutiae?', '["Ridge endings, bifurcations, dots", "Lines, curves, circles", "Red, blue, green", "Large, medium, small"]'::jsonb, 0, 'hard', 'Minutiae are the unique ridge characteristics like endings, bifurcations, and dots.'),
('cr_078', 'criminalistics', 'Forensic Ballistics', 'What is the difference between internal and external ballistics?', '["Inside gun vs. projectile in flight", "Big vs. small gun", "Old vs. new gun", "Legal vs. illegal gun"]'::jsonb, 0, 'hard', 'Internal ballistics studies bullet behavior inside the gun; external ballistics studies it in flight.'),
