('cr_083', 'criminalistics', 'Legal Medicine', 'What is algor mortis?', '["Cooling of body after death", "Muscle stiffening", "Skin discoloration", "Decomposition"]'::jsonb, 0, 'hard', 'Algor mortis is the gradual cooling of the body after death.'),
('cr_084', 'criminalistics', 'DNA Analysis', 'What is PCR in DNA analysis?', '["Polymerase Chain Reaction", "Police Crime Report", "Physical Crime Recording", "Preliminary Crime Review"]'::jsonb, 0, 'hard', 'PCR (Polymerase Chain Reaction) is a technique to amplify small DNA samples.'),
('cr_085', 'criminalistics', 'Forensic Chemistry', 'What is chromatography in forensics?', '["Technique to separate mixtures", "Photography method", "Fingerprint analysis", "Document examination"]'::jsonb, 0, 'hard', 'Chromatography separates mixtures into components for analysis of drugs, poisons, etc.'),
('cdi_041', 'crime_detection', 'Fundamentals of Criminal Investigation', 'What is the primary purpose of criminal investigation?', '["Identify and apprehend offenders", "Punish criminals", "Release prisoners", "Write laws"]'::jsonb, 0, 'easy', 'Criminal investigation aims to identify, apprehend, and gather evidence against offenders.'),
('cdi_042', 'crime_detection', 'Fundamentals of Criminal Investigation', 'What are the 3 I''s of criminal investigation?', '["Information, Instrumentation, Interviewing", "Investigation, Interrogation, Incarceration", "Identification, Inspection, Intelligence", "Inquiry, Inquest, Indictment"]'::jsonb, 0, 'easy', 'The 3 I''s are Information (gathering), Instrumentation (forensic tools), and Interviewing.'),
('cdi_043', 'crime_detection', 'Fundamentals of Criminal Investigation', 'What is a crime scene?', '["Location where crime occurred", "Police station", "Court room", "Prison"]'::jsonb, 0, 'easy', 'A crime scene is the location where a criminal act took place.'),
