('crm_045', 'criminology', 'Human Behavior and Victimology', 'What is victimology?', '["Study of crime victims", "Study of criminals", "Study of police", "Study of laws"]'::jsonb, 0, 'easy', 'Victimology is the scientific study of crime victims.'),
('crm_046', 'criminology', 'Human Behavior and Victimology', 'What is victim precipitation?', '["Victim contributed to the crime", "Victim is innocent", "Victim is protected", "Victim is compensated"]'::jsonb, 0, 'easy', 'Victim precipitation suggests the victim may have contributed to the criminal event.'),
('crm_047', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'What is juvenile delinquency?', '["Criminal behavior by minors", "Adult crime", "White collar crime", "Organized crime"]'::jsonb, 0, 'easy', 'Juvenile delinquency refers to criminal or antisocial behavior by minors.'),
('crm_048', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'What is RA 9344?', '["Juvenile Justice and Welfare Act", "Anti-Drug Law", "Anti-Trafficking Law", "Cybercrime Law"]'::jsonb, 0, 'easy', 'RA 9344 is the Juvenile Justice and Welfare Act of 2006.'),
('crm_049', 'criminology', 'Professional Conduct and Ethical Standards', 'What is ethics in criminology?', '["Moral principles guiding conduct", "Criminal behavior", "Police procedures", "Court rules"]'::jsonb, 0, 'easy', 'Ethics refers to moral principles that guide professional conduct.'),
('crm_050', 'criminology', 'Criminological Research', 'What is the purpose of criminological research?', '["Understand and prevent crime", "Punish criminals", "Release prisoners", "Write laws"]'::jsonb, 0, 'easy', 'Criminological research aims to understand crime causes and develop prevention strategies.'),
('crm_051', 'criminology', 'Theories of Crime Causation', 'What is Sutherland''s Differential Association Theory?', '["Crime learned through interaction", "Crime is genetic", "Crime is random", "Crime is biological"]'::jsonb, 0, 'hard', 'Differential Association Theory states that criminal behavior is learned through social interaction.'),
('crm_052', 'criminology', 'Theories of Crime Causation', 'What is Merton''s Strain Theory?', '["Crime from gap between goals and means", "Crime is genetic", "Crime is learned", "Crime is random"]'::jsonb, 0, 'hard', 'Strain Theory suggests crime results from the gap between cultural goals and legitimate means.'),
('crm_053', 'criminology', 'Theories of Crime Causation', 'What is Hirschi''s Social Bond Theory?', '["Weak social bonds lead to crime", "Strong bonds cause crime", "Bonds are irrelevant", "Only family matters"]'::jsonb, 0, 'hard', 'Social Bond Theory proposes that weak social bonds increase likelihood of criminal behavior.'),
('crm_054', 'criminology', 'Theories of Crime Causation', 'What is Labeling Theory?', '["Labels create criminal identity", "Labels prevent crime", "Labels are irrelevant", "Labels help rehabilitation"]'::jsonb, 0, 'hard', 'Labeling Theory suggests that being labeled as criminal can lead to more criminal behavior.'),
('crm_055', 'criminology', 'Theories of Crime Causation', 'What is Routine Activities Theory?', '["Crime needs target, offender, no guardian", "Crime is random", "Crime is planned", "Crime needs motive only"]'::jsonb, 0, 'hard', 'Routine Activities Theory states crime occurs with a motivated offender, suitable target, and lack of guardian.')
INSERT INTO questions (id, subject, topic, question_text, options, correct_answer_index, difficulty, explanation) VALUES
('ca_031', 'corrections', 'Institutional Corrections', 'What is a prison?', '["Facility for convicted criminals", "Police station", "Court house", "Hospital"]'::jsonb, 0, 'easy', 'A prison is a facility where convicted criminals serve their sentences.'),
('ca_032', 'corrections', 'Institutional Corrections', 'What is the purpose of imprisonment?', '["Punishment and rehabilitation", "Entertainment", "Education only", "Employment"]'::jsonb, 0, 'easy', 'Imprisonment serves to punish offenders and rehabilitate them for reintegration.'),
('ca_033', 'corrections', 'Institutional Corrections', 'What is the Bureau of Corrections?', '["Agency managing national prisons", "Police agency", "Court system", "Prosecution office"]'::jsonb, 0, 'easy', 'The Bureau of Corrections manages national prisons in the Philippines.'),
('ca_034', 'corrections', 'Non-Institutional Corrections', 'What is probation?', '["Community supervision instead of prison", "Prison sentence", "Death penalty", "Fine only"]'::jsonb, 0, 'easy', 'Probation allows offenders to serve their sentence in the community under supervision.'),
('ca_035', 'corrections', 'Non-Institutional Corrections', 'What is parole?', '["Early release with supervision", "Full pardon", "Death sentence", "Life imprisonment"]'::jsonb, 0, 'easy', 'Parole is the conditional release of a prisoner before completing their sentence.'),
('ca_036', 'corrections', 'Pardon and Amnesty', 'What is pardon?', '["Executive clemency forgiving offense", "Court decision", "Police action", "Prosecution decision"]'::jsonb, 0, 'easy', 'Pardon is an act of executive clemency that forgives the offense and its consequences.'),
('ca_037', 'corrections', 'Pardon and Amnesty', 'What is amnesty?', '["General pardon for political offenses", "Individual pardon", "Court decision", "Police action"]'::jsonb, 0, 'easy', 'Amnesty is a general pardon granted to a group, usually for political offenses.'),
('ca_038', 'corrections', 'Rehabilitation Programs', 'What is the goal of rehabilitation?', '["Reform offenders for reintegration", "Maximum punishment", "Isolation forever", "Execution"]'::jsonb, 0, 'easy', 'Rehabilitation aims to reform offenders so they can successfully reintegrate into society.'),
('ca_039', 'corrections', 'Rehabilitation Programs', 'What is vocational training in prison?', '["Teaching job skills to inmates", "Academic education only", "Physical exercise", "Religious study"]'::jsonb, 0, 'easy', 'Vocational training teaches inmates practical job skills for employment after release.'),
('ca_040', 'corrections', 'Inmate Classification', 'Why are inmates classified?', '["For proper placement and treatment", "Random assignment", "By alphabet", "By height"]'::jsonb, 0, 'easy', 'Classification ensures inmates are placed appropriately based on security and treatment needs.'),
('ca_041', 'corrections', 'Institutional Corrections', 'What is the Pennsylvania System?', '["Solitary confinement and labor", "Group housing", "Open prison", "No work"]'::jsonb, 0, 'hard', 'The Pennsylvania System emphasized solitary confinement with in-cell labor.'),
('ca_042', 'corrections', 'Institutional Corrections', 'What is the Auburn System?', '["Silent work together, separate at night", "Complete solitary", "Open living", "No discipline"]'::jsonb, 0, 'hard', 'The Auburn System had prisoners work silently together during day but separate at night.'),
('ca_043', 'corrections', 'Non-Institutional Corrections', 'What is the difference between parole and probation?', '["Parole after prison, probation instead of", "Same thing", "Both after prison", "Neither involves supervision"]'::jsonb, 0, 'hard', 'Parole is release after serving part of prison sentence; probation is instead of imprisonment.'),
('ca_044', 'corrections', 'Therapeutic Communities', 'What is a therapeutic community?', '["Treatment environment for rehabilitation", "Maximum security prison", "Death row", "Isolation unit"]'::jsonb, 0, 'hard', 'A therapeutic community is a treatment environment focused on behavioral change and rehabilitation.'),
('ca_045', 'corrections', 'Prison Security', 'What are the security levels in Philippine prisons?', '["Maximum, medium, minimum", "High, low", "Only maximum", "No classification"]'::jsonb, 0, 'hard', 'Philippine prisons have maximum, medium, and minimum security classifications.'),
('cj_086', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is the principle of conspiracy?', '["Agreement to commit a crime", "Solo criminal act", "Accidental crime", "Self-defense"]'::jsonb, 0, 'medium', 'Conspiracy exists when two or more persons agree to commit a crime and decide to commit it.'),
('cj_087', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is proposal to commit a crime?', '["Proposing to another to commit a crime", "Planning alone", "Attempted crime", "Frustrated crime"]'::jsonb, 0, 'medium', 'Proposal is when a person proposes to another the commission of a crime.'),
('cj_088', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is the crime of rape under RA 8353?', '["Crime against persons", "Crime against property", "Crime against public order", "Crime against morals"]'::jsonb, 0, 'medium', 'Under RA 8353, rape is reclassified as a crime against persons, not chastity.'),
('cj_089', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is the penalty for robbery with force upon things?', '["Prision correccional to prision mayor", "Death penalty", "Fine only", "Reclusion perpetua"]'::jsonb, 0, 'medium', 'Robbery with force upon things is punishable by prision correccional to prision mayor.'),
('cj_090', 'criminal_jurisprudence', 'Criminal Procedure', 'What is a complaint in criminal procedure?', '["Sworn statement by offended party", "Court decision", "Police report", "Prosecutor motion"]'::jsonb, 0, 'medium', 'A complaint is a sworn written statement charging a person with an offense.'),
('cj_091', 'criminal_jurisprudence', 'Criminal Procedure', 'What is an information in criminal procedure?', '["Accusation filed by prosecutor", "Private complaint", "Court order", "Defense motion"]'::jsonb, 0, 'medium', 'An information is an accusation in writing filed by the prosecutor.'),
('cj_092', 'criminal_jurisprudence', 'Rules of Evidence', 'What is the rule on illegally obtained evidence?', '["Inadmissible as fruit of poisonous tree", "Always admissible", "Admissible with penalty", "Judge decides"]'::jsonb, 0, 'medium', 'Evidence obtained illegally is inadmissible under the exclusionary rule.'),
('cj_093', 'criminal_jurisprudence', 'Rules of Evidence', 'What is res gestae?', '["Spontaneous statements during event", "Written confession", "Expert testimony", "Documentary evidence"]'::jsonb, 0, 'medium', 'Res gestae are spontaneous statements made during or immediately after an event.'),
('cj_094', 'criminal_jurisprudence', 'Criminal Law Book I', 'What are alternative circumstances?', '["May be mitigating or aggravating", "Always mitigating", "Always aggravating", "Neither"]'::jsonb, 0, 'medium', 'Alternative circumstances may be mitigating or aggravating depending on the case.'),
('cj_095', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is intoxication as a circumstance?', '["Alternative circumstance", "Always mitigating", "Always aggravating", "Always exempting"]'::jsonb, 0, 'medium', 'Intoxication is an alternative circumstance - mitigating if not habitual or intentional.'),
('lea_086', 'law_enforcement', 'Police Organization and Administration', 'What is the chain of command in the PNP?', '["Hierarchical authority structure", "Random assignment", "No structure", "Democratic voting"]'::jsonb, 0, 'medium', 'Chain of command is the hierarchical structure of authority in the police organization.'),
('lea_087', 'law_enforcement', 'Police Organization and Administration', 'What is unity of command principle?', '["One supervisor per subordinate", "Multiple supervisors", "No supervision", "Self-supervision"]'::jsonb, 0, 'medium', 'Unity of command means each subordinate reports to only one supervisor.'),
('lea_088', 'law_enforcement', 'Police Patrol Operations', 'What is selective patrol?', '["Patrol based on crime analysis", "Random patrol", "No patrol", "Continuous patrol everywhere"]'::jsonb, 0, 'medium', 'Selective patrol deploys officers based on crime patterns and analysis.'),
('lea_089', 'law_enforcement', 'Police Patrol Operations', 'What is directed patrol?', '["Patrol focused on specific areas or crimes", "Random walking", "Office duty only", "Administrative work"]'::jsonb, 0, 'medium', 'Directed patrol focuses on specific locations, times, or types of criminal activity.'),
('lea_090', 'law_enforcement', 'Police Intelligence', 'What is covert operation?', '["Secret police operation", "Public operation", "Media operation", "Community meeting"]'::jsonb, 0, 'medium', 'A covert operation is conducted secretly without revealing police involvement.'),
('lea_091', 'law_enforcement', 'Police Intelligence', 'What is surveillance in police work?', '["Close observation of persons or places", "Public announcement", "Community meeting", "Press conference"]'::jsonb, 0, 'medium', 'Surveillance is the systematic observation of persons, places, or things.'),
('lea_092', 'law_enforcement', 'Industrial Security Administration', 'What is access control in security?', '["Controlling entry to premises", "Open access policy", "No security", "Random entry"]'::jsonb, 0, 'medium', 'Access control regulates who can enter specific areas or facilities.'),
('lea_093', 'law_enforcement', 'Industrial Security Administration', 'What is perimeter security?', '["Protection of facility boundaries", "Interior security only", "Personal security", "Information security"]'::jsonb, 0, 'medium', 'Perimeter security protects the outer boundaries of a facility.'),
('lea_094', 'law_enforcement', 'Police Personnel Management', 'What is the attrition system in PNP?', '["Removal for failing standards", "Promotion system", "Training program", "Recruitment process"]'::jsonb, 0, 'medium', 'The attrition system removes personnel who fail to meet performance standards.'),
('lea_095', 'law_enforcement', 'Police Records Management', 'What is police clearance?', '["Certificate of no criminal record", "Arrest warrant", "Court decision", "Complaint"]'::jsonb, 0, 'medium', 'Police clearance certifies that a person has no pending criminal case.'),
('cr_086', 'criminalistics', 'Personal Identification', 'What is the Henry System of fingerprint classification?', '["System using patterns and ridge counts", "Blood typing system", "DNA classification", "Hair analysis"]'::jsonb, 0, 'medium', 'The Henry System classifies fingerprints based on patterns and ridge counts.'),
('cr_087', 'criminalistics', 'Personal Identification', 'What is a latent fingerprint?', '["Invisible print requiring development", "Visible bloody print", "Plastic impression", "Ink print"]'::jsonb, 0, 'medium', 'Latent prints are invisible fingerprints that require chemical or physical development.'),
('cr_088', 'criminalistics', 'Police Photography', 'What is the purpose of evidence photography?', '["Document evidence for court", "Personal collection", "Artistic expression", "News reporting"]'::jsonb, 0, 'medium', 'Evidence photography documents physical evidence for presentation in court.'),
('cr_089', 'criminalistics', 'Forensic Ballistics', 'What are class characteristics in ballistics?', '["Features common to all guns of same type", "Unique to one gun", "Random marks", "No characteristics"]'::jsonb, 0, 'medium', 'Class characteristics are shared by all firearms of the same make and model.'),
('cr_090', 'criminalistics', 'Forensic Ballistics', 'What are individual characteristics in ballistics?', '["Marks unique to a specific gun", "Common to all guns", "Random scratches", "Manufacturing marks"]'::jsonb, 0, 'medium', 'Individual characteristics are unique marks that identify a specific firearm.'),
('cr_091', 'criminalistics', 'Questioned Documents Examination', 'What is a standard or exemplar in document examination?', '["Known sample for comparison", "Questioned document", "Forged document", "Anonymous document"]'::jsonb, 0, 'medium', 'A standard is a known genuine sample used to compare with questioned documents.'),
('cr_092', 'criminalistics', 'Questioned Documents Examination', 'What is a forgery?', '["False document made to deceive", "Original document", "Photocopy", "Legal duplicate"]'::jsonb, 0, 'medium', 'Forgery is the creation of a false document intended to deceive.'),
('cr_093', 'criminalistics', 'Legal Medicine', 'What is cadaveric spasm?', '["Instant rigidity at death", "Normal rigor mortis", "Decomposition", "Body cooling"]'::jsonb, 0, 'medium', 'Cadaveric spasm is instant rigidity of muscles at the moment of death.'),
('cr_094', 'criminalistics', 'Legal Medicine', 'What is the medico-legal officer?', '["Doctor trained in legal medicine", "Police officer", "Prosecutor", "Judge"]'::jsonb, 0, 'medium', 'A medico-legal officer is a physician trained in applying medicine to legal matters.'),
('cr_095', 'criminalistics', 'DNA Analysis', 'What biological samples can provide DNA?', '["Blood, saliva, hair, skin cells", "Only blood", "Only saliva", "Only hair"]'::jsonb, 0, 'medium', 'DNA can be extracted from blood, saliva, hair roots, skin cells, and other tissues.'),
('cdi_061', 'crime_detection', 'Fundamentals of Criminal Investigation', 'What is modus operandi?', '["Method of operation used by criminal", "Legal procedure", "Court process", "Police protocol"]'::jsonb, 0, 'medium', 'Modus operandi is the method or pattern used by a criminal to commit crimes.'),
('cdi_062', 'crime_detection', 'Fundamentals of Criminal Investigation', 'What is the corpus delicti?', '["Body of the crime - proof crime occurred", "Dead body only", "Criminal identity", "Weapon used"]'::jsonb, 0, 'medium', 'Corpus delicti means the body of the crime - evidence that a crime actually occurred.'),
('cdi_063', 'crime_detection', 'Crime Scene Investigation', 'What is physical evidence?', '["Tangible objects related to crime", "Witness testimony", "Suspect confession", "Expert opinion"]'::jsonb, 0, 'medium', 'Physical evidence consists of tangible objects connected to the crime.'),
('cdi_064', 'crime_detection', 'Crime Scene Investigation', 'What is trace evidence?', '["Small materials transferred during crime", "Large objects", "Weapons only", "Documents only"]'::jsonb, 0, 'medium', 'Trace evidence includes small materials like hair, fibers, and glass transferred during a crime.'),
('cdi_065', 'crime_detection', 'Traffic Management', 'What is traffic engineering?', '["Scientific approach to traffic safety", "Car repair", "Road construction only", "Vehicle manufacturing"]'::jsonb, 0, 'medium', 'Traffic engineering applies scientific principles to improve traffic flow and safety.'),
('cdi_066', 'crime_detection', 'Accident Investigation', 'What is skid marks analysis?', '["Examining tire marks to determine speed", "Cleaning roads", "Painting roads", "Building roads"]'::jsonb, 0, 'medium', 'Skid marks analysis helps determine vehicle speed before an accident.'),
('cdi_067', 'crime_detection', 'Drug Education and Vice Control', 'What is drug pushing?', '["Selling illegal drugs", "Using drugs", "Manufacturing drugs", "Transporting only"]'::jsonb, 0, 'medium', 'Drug pushing is the illegal sale or distribution of dangerous drugs.'),
('cdi_068', 'crime_detection', 'Drug Education and Vice Control', 'What is drug dependency?', '["Physical or psychological need for drugs", "Occasional use", "Medical use", "No use"]'::jsonb, 0, 'medium', 'Drug dependency is the compulsive physical or psychological need for drugs.'),
('cdi_069', 'crime_detection', 'Fire Technology', 'What is the point of origin in fire investigation?', '["Location where fire started", "Where fire ended", "Largest damage area", "Exit point"]'::jsonb, 0, 'medium', 'The point of origin is the specific location where a fire began.'),
('cdi_070', 'crime_detection', 'Fire Technology', 'What are accelerants in arson?', '["Substances used to spread fire faster", "Fire extinguishers", "Fireproof materials", "Safety equipment"]'::jsonb, 0, 'medium', 'Accelerants are flammable substances used to start or spread fire in arson.'),
('crm_056', 'criminology', 'Theories of Crime Causation', 'What is the Anomie Theory?', '["Crime from breakdown of social norms", "Crime is genetic", "Crime is learned", "Crime is random"]'::jsonb, 0, 'medium', 'Anomie Theory suggests crime results from a breakdown of social norms.'),
('crm_057', 'criminology', 'Theories of Crime Causation', 'What is social disorganization theory?', '["Crime from weak community control", "Crime is biological", "Crime is genetic", "Crime is random"]'::jsonb, 0, 'medium', 'Social disorganization theory links crime to weak community social controls.'),
('crm_058', 'criminology', 'Human Behavior and Victimology', 'What is a repeat victim?', '["Person victimized multiple times", "First-time victim", "Never victimized", "Offender"]'::jsonb, 0, 'medium', 'A repeat victim is someone who has been victimized more than once.'),
('crm_059', 'criminology', 'Human Behavior and Victimology', 'What is victim compensation?', '["Financial assistance to crime victims", "Punishment of offender", "Pardon", "Parole"]'::jsonb, 0, 'medium', 'Victim compensation provides financial assistance to crime victims.'),
('crm_060', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'What is diversion under RA 9344?', '["Alternative to formal court process", "Imprisonment", "Death penalty", "Life sentence"]'::jsonb, 0, 'medium', 'Diversion provides juvenile offenders an alternative to the formal justice system.'),
('crm_061', 'criminology', 'Juvenile Delinquency and Juvenile Justice', 'What is a status offense?', '["Offense only because of minor status", "Serious crime", "Adult crime", "No offense"]'::jsonb, 0, 'medium', 'Status offenses are acts that are offenses only because the person is a minor.'),
('crm_062', 'criminology', 'Professional Conduct and Ethical Standards', 'What is professional integrity?', '["Adherence to ethical standards", "Breaking rules", "Personal interest first", "Corruption"]'::jsonb, 0, 'medium', 'Professional integrity means consistently adhering to ethical standards.'),
('crm_063', 'criminology', 'Criminological Research', 'What is a case study in criminology?', '["In-depth study of single case", "Survey of many", "Experiment", "Statistical analysis"]'::jsonb, 0, 'medium', 'A case study is an in-depth examination of a single case or a small number of cases.'),
('crm_064', 'criminology', 'Criminological Research', 'What is recidivism rate?', '["Rate of repeat offending", "First offense rate", "Crime clearance rate", "Conviction rate"]'::jsonb, 0, 'medium', 'Recidivism rate measures how many released offenders commit new crimes.'),
('crm_065', 'criminology', 'Dispute Resolution and Crisis Management', 'What is mediation?', '["Third party helps resolve dispute", "Court trial", "Arrest", "Punishment"]'::jsonb, 0, 'medium', 'Mediation involves a neutral third party helping disputants reach agreement.'),
('ca_046', 'corrections', 'Institutional Corrections', 'What is the New Bilibid Prison?', '["National penitentiary in Muntinlupa", "Provincial jail", "City jail", "Police station"]'::jsonb, 0, 'medium', 'New Bilibid Prison is the national penitentiary located in Muntinlupa City.'),
('ca_047', 'corrections', 'Institutional Corrections', 'What is a penal colony?', '["Agricultural prison settlement", "Maximum security prison", "City jail", "Police detention"]'::jsonb, 0, 'medium', 'A penal colony is a prison settlement where inmates engage in agricultural work.'),
('ca_048', 'corrections', 'Non-Institutional Corrections', 'What are the conditions of probation?', '["Rules probationer must follow", "No conditions", "Prison rules", "Parole rules"]'::jsonb, 0, 'medium', 'Probation conditions are rules the probationer must follow during supervision.'),
('ca_049', 'corrections', 'Non-Institutional Corrections', 'Who grants parole in the Philippines?', '["Board of Pardons and Parole", "Judge", "Prosecutor", "Police"]'::jsonb, 0, 'medium', 'The Board of Pardons and Parole grants parole to qualified prisoners.'),
('ca_050', 'corrections', 'Pardon and Amnesty', 'What is commutation of sentence?', '["Reducing the penalty imposed", "Increasing penalty", "Full pardon", "No change"]'::jsonb, 0, 'medium', 'Commutation reduces the penalty imposed without forgiving the offense.'),
('ca_051', 'corrections', 'Rehabilitation Programs', 'What is behavior modification in prison?', '["Changing inmate behavior through programs", "Punishment only", "No programs", "Isolation"]'::jsonb, 0, 'medium', 'Behavior modification uses structured programs to change inmate behavior.'),
('ca_052', 'corrections', 'Rehabilitation Programs', 'What is work release program?', '["Inmates work outside during day", "No work allowed", "Forced labor", "Work inside only"]'::jsonb, 0, 'medium', 'Work release allows inmates to work outside prison during the day.'),
('ca_053', 'corrections', 'Inmate Classification', 'What is maximum security classification?', '["For most dangerous inmates", "For all inmates", "For first offenders", "For minor offenses"]'::jsonb, 0, 'medium', 'Maximum security is for the most dangerous inmates requiring highest supervision.'),
('ca_054', 'corrections', 'Inmate Classification', 'What is minimum security classification?', '["For low-risk inmates", "For dangerous inmates", "For death row", "No classification"]'::jsonb, 0, 'medium', 'Minimum security is for low-risk inmates who need minimal supervision.'),
('ca_055', 'corrections', 'Prison Security', 'What is a prison lockdown?', '["Confining all inmates to cells", "Normal operation", "Releasing inmates", "Open visitation"]'::jsonb, 0, 'medium', 'A lockdown confines all inmates to their cells during emergencies or security threats.'),
('cj_096', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is the doctrine of implied conspiracy?', '["Conspiracy inferred from coordinated acts", "Express agreement needed", "No conspiracy exists", "Only written agreement"]'::jsonb, 0, 'hard', 'Implied conspiracy is inferred from the coordinated acts of the accused showing common purpose.'),
('cj_097', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is the principle of absorption in criminal law?', '["Lesser crime absorbed in graver offense", "All crimes punished separately", "No absorption", "Only in civil cases"]'::jsonb, 0, 'hard', 'Absorption means a lesser crime is absorbed when it is a necessary means to commit the graver offense.'),
('cj_098', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is the doctrine of variance?', '["Difference between charge and proof", "Identical charge and proof", "No charge needed", "Only for civil cases"]'::jsonb, 0, 'hard', 'Variance occurs when there is a material difference between the allegations and proof.'),
('cj_099', 'criminal_jurisprudence', 'Criminal Law Book II', 'What are qualifying circumstances in murder?', '["Circumstances that make homicide murder", "Mitigating factors", "Exempting factors", "Absolutory causes"]'::jsonb, 0, 'hard', 'Qualifying circumstances like treachery and premeditation elevate homicide to murder.'),
('cj_100', 'criminal_jurisprudence', 'Criminal Procedure', 'What is the rule on double jeopardy?', '["No second prosecution for same offense", "Multiple trials allowed", "Appeals are jeopardy", "No protection exists"]'::jsonb, 0, 'hard', 'Double jeopardy prevents a second prosecution for the same offense after acquittal or conviction.'),
('cj_101', 'criminal_jurisprudence', 'Criminal Procedure', 'What is the Miranda doctrine?', '["Right to counsel and silence during custodial investigation", "No rights during arrest", "Rights only in court", "Only for serious crimes"]'::jsonb, 0, 'hard', 'Miranda rights include the right to remain silent and to have counsel during custodial investigation.'),
('cj_102', 'criminal_jurisprudence', 'Rules of Evidence', 'What is the doctrine of res inter alios acta?', '["Acts of others not binding on accused", "All acts are admissible", "No exclusionary rule", "Only confessions matter"]'::jsonb, 0, 'hard', 'Res inter alios acta means the acts of third parties are not admissible against the accused.'),
('cj_103', 'criminal_jurisprudence', 'Rules of Evidence', 'What is the dying declaration exception?', '["Statement by person believing death imminent", "Any deathbed statement", "Written will only", "No exception exists"]'::jsonb, 0, 'hard', 'A dying declaration is admissible if made by a person who believes death is imminent regarding its cause.'),
('cj_104', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is praeter intentionem?', '["Result exceeds intent", "Intent matches result", "No intent needed", "Accidental crime"]'::jsonb, 0, 'hard', 'Praeter intentionem means the resulting injury is greater than what was intended.'),
('cj_105', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is the Anti-Hazing Law penalty?', '["Reclusion perpetua if death results", "Fine only", "Probation always", "Community service"]'::jsonb, 0, 'hard', 'Under RA 11053, hazing resulting in death is punishable by reclusion perpetua.'),
('cj_106', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is the Revised Penal Code?', '["Act No. 3815", "Act No. 3814", "RA 9165", "RA 8353"]'::jsonb, 0, 'easy', 'The Revised Penal Code is Act No. 3815, taking effect January 1, 1932.'),
('cj_107', 'criminal_jurisprudence', 'Criminal Law Book I', 'What are the sources of criminal law?', '["Constitution, statutes, treaties", "Custom only", "Religion only", "Tradition only"]'::jsonb, 0, 'easy', 'Criminal law comes from the Constitution, legislative acts, and treaties.'),
('cj_108', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is the principle of pro reo?', '["Doubt resolved in favor of accused", "Against the accused", "Neutral", "Random"]'::jsonb, 0, 'easy', 'Pro reo means doubts are resolved in favor of the accused.'),
('cj_109', 'criminal_jurisprudence', 'Criminal Procedure', 'What is the right to counsel?', '["Right to have a lawyer", "Right to remain silent", "Right to bail", "Right to appeal"]'::jsonb, 0, 'easy', 'The right to counsel guarantees legal representation.'),
('cj_110', 'criminal_jurisprudence', 'Criminal Procedure', 'What is double jeopardy?', '["Cannot be tried twice for same offense", "Two trials allowed", "Multiple charges allowed", "No protection"]'::jsonb, 0, 'easy', 'Double jeopardy protects against being tried twice for the same offense.'),
('cj_111', 'criminal_jurisprudence', 'Rules of Evidence', 'What is direct evidence?', '["Evidence proving fact without inference", "Circumstantial evidence", "Hearsay", "Opinion"]'::jsonb, 0, 'easy', 'Direct evidence proves a fact without need for inference.'),
('cj_112', 'criminal_jurisprudence', 'Criminal Procedure', 'What is venue in criminal cases?', '["Place where crime was committed", "Any court", "Accuser choice", "Random assignment"]'::jsonb, 0, 'easy', 'Criminal cases are generally tried where the crime was committed.'),
('cj_113', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is territorial jurisdiction?', '["RPC applies within Philippine territory", "Worldwide application", "No limits", "Foreign courts"]'::jsonb, 0, 'easy', 'The RPC generally applies only within Philippine territory.'),
('cj_114', 'criminal_jurisprudence', 'Rules of Evidence', 'What is circumstantial evidence?', '["Evidence requiring inference", "Direct proof", "Confession", "Physical evidence only"]'::jsonb, 0, 'easy', 'Circumstantial evidence requires inference to prove a fact.'),
('cj_115', 'criminal_jurisprudence', 'Criminal Procedure', 'What is information in criminal procedure?', '["Formal charge filed by prosecutor", "Complaint by victim", "Police report", "Witness statement"]'::jsonb, 0, 'easy', 'An information is the formal charge filed in court by the prosecutor.'),
('cj_116', 'criminal_jurisprudence', 'Criminal Procedure', 'What is complaint in criminal procedure?', '["Sworn statement charging offense", "Court decision", "Appeal", "Motion"]'::jsonb, 0, 'easy', 'A complaint is a sworn written statement charging a person with an offense.'),
