('cj_119', 'criminal_jurisprudence', 'Criminal Law Book II', 'What is treason?', '["Levying war or adhering to enemies", "Regular crime", "Property crime", "Personal crime"]'::jsonb, 0, 'hard', 'Treason is levying war against Philippines or adhering to its enemies.'),
('cj_120', 'criminal_jurisprudence', 'Criminal Law Book I', 'What is absolutory cause?', '["Cause that absolves offender from liability", "Increases penalty", "No effect", "Justifying only"]'::jsonb, 0, 'hard', 'Absolutory causes exempt from criminal liability similar to justifying circumstances.')
