('crm_090', 'criminology', 'Human Behavior and Crisis Management', 'What is situational crime prevention?', '["Reducing crime opportunities", "Changing offender psychology", "Punishment focus", "Rehabilitation focus"]'::jsonb, 0, 'medium', 'Situational prevention focuses on reducing opportunities for crime.'),
('crm_091', 'criminology', 'Professional Conduct and Ethical Standards', 'What is ethical dilemma in criminal justice?', '["Conflict between competing moral principles", "Clear right answer", "No moral issues", "Simple decisions"]'::jsonb, 0, 'medium', 'Ethical dilemmas involve difficult choices between competing moral principles.'),
