('cr_124', 'criminalistics', 'Personal Identification', 'What is a latent fingerprint?', '["Invisible print requiring processing", "Visible print", "Fake print", "Partial print"]'::jsonb, 0, 'medium', 'Latent fingerprints are invisible and require powder or chemicals to reveal.'),
('cr_125', 'criminalistics', 'DNA Analysis', 'What biological samples contain DNA?', '["Blood, saliva, hair, skin cells", "Only blood", "Only saliva", "Only hair"]'::jsonb, 0, 'medium', 'DNA can be extracted from various biological materials including blood, saliva, and hair.'),
('cr_126', 'criminalistics', 'Questioned Documents Examination', 'What is a watermark?', '["Design embedded in paper during manufacture", "Ink stain", "Coffee stain", "Signature"]'::jsonb, 0, 'medium', 'A watermark is a design impressed into paper during manufacturing for security.'),
