('cr_129', 'criminalistics', 'Forensic Ballistics', 'What is terminal ballistics?', '["Study of projectile behavior at impact", "Bullet manufacturing", "Gun cleaning", "Target practice"]'::jsonb, 0, 'hard', 'Terminal ballistics studies projectile behavior when striking a target.'),
('cr_130', 'criminalistics', 'DNA Analysis', 'What is STR analysis?', '["Short Tandem Repeat DNA profiling", "Single Test Result", "Standard Testing Report", "Sample Transfer Record"]'::jsonb, 0, 'hard', 'STR analysis examines short tandem repeats in DNA for identification.'),
('cr_131', 'criminalistics', 'Toxicology', 'What is postmortem redistribution?', '["Drug movement in body after death", "Drug storage", "Drug disposal", "Drug detection"]'::jsonb, 0, 'hard', 'Postmortem redistribution is drug concentration changes in tissues after death.'),
