('cr_134', 'criminalistics', 'Forensic Chemistry', 'What is spectrophotometry?', '["Measuring light absorption by substances", "Weighing evidence", "Photographing scenes", "Recording audio"]'::jsonb, 0, 'hard', 'Spectrophotometry measures how substances absorb light for identification.'),
('cr_135', 'criminalistics', 'Legal Medicine', 'What is tache noire?', '["Dark band on exposed eyeball after death", "Bruising", "Bleeding", "Scarring"]'::jsonb, 0, 'hard', 'Tache noire is a dark band appearing on the exposed part of the eyeball after death.'),
('lea_121', 'law_enforcement', 'Police Organization', 'What is the chain of command?', '["Hierarchical structure of authority", "Physical restraints", "Evidence chain", "Communication system"]'::jsonb, 0, 'medium', 'Chain of command is the hierarchical line of authority in police organizations.'),
('lea_122', 'law_enforcement', 'Police Operations', 'What is beat patrol?', '["Assigned area for regular patrol", "Special operations", "Headquarters duty", "Training exercise"]'::jsonb, 0, 'medium', 'Beat patrol involves officers patrolling assigned geographic areas regularly.'),
('lea_123', 'law_enforcement', 'Human Rights', 'What is due process?', '["Fair treatment through judicial system", "Quick arrest", "Immediate punishment", "Delayed trial"]'::jsonb, 0, 'medium', 'Due process ensures fair treatment and legal procedures in criminal justice.'),
('lea_124', 'law_enforcement', 'Police Ethics', 'What is police discretion?', '["Officer judgment in applying law", "No choices allowed", "Automatic responses", "Computer decisions"]'::jsonb, 0, 'medium', 'Police discretion is an officer''s freedom to choose how to handle situations.'),
('lea_125', 'law_enforcement', 'Police Organization', 'What is unity of command?', '["One supervisor per subordinate", "Multiple bosses", "No supervision", "Self-management"]'::jsonb, 0, 'medium', 'Unity of command means each person reports to only one supervisor.'),
('lea_126', 'law_enforcement', 'Police Planning', 'What is strategic planning in policing?', '["Long-term organizational goals", "Daily schedules", "Individual tasks", "Budget only"]'::jsonb, 0, 'hard', 'Strategic planning establishes long-term goals and direction for police agencies.'),
('lea_127', 'law_enforcement', 'Police Operations', 'What is intelligence-led policing?', '["Using data analysis to guide operations", "Random patrols", "Reactive policing only", "No planning"]'::jsonb, 0, 'hard', 'Intelligence-led policing uses crime data analysis to direct police resources.'),
('lea_128', 'law_enforcement', 'Police Administration', 'What is POSDCORB?', '["Management functions framework", "Police rank", "Crime type", "Training program"]'::jsonb, 0, 'hard', 'POSDCORB stands for Planning, Organizing, Staffing, Directing, Coordinating, Reporting, Budgeting.'),
('lea_129', 'law_enforcement', 'Police Ethics', 'What is the blue wall of silence?', '["Code against reporting fellow officers", "Communication system", "Uniform color", "Prison term"]'::jsonb, 0, 'hard', 'Blue wall of silence refers to officers not reporting misconduct of colleagues.'),
('lea_130', 'law_enforcement', 'Police Operations', 'What is hot spots policing?', '["Focusing resources on high-crime areas", "Weather-based deployment", "Uniform assignment", "Random patrol"]'::jsonb, 0, 'hard', 'Hot spots policing concentrates police presence in areas with high crime rates.'),
('lea_131', 'law_enforcement', 'Police Administration', 'What is zero-based budgeting?', '["Justifying all expenses from scratch", "No budget", "Incremental budgeting", "Fixed budget"]'::jsonb, 0, 'hard', 'Zero-based budgeting requires justifying all expenses each budget period.'),
('lea_132', 'law_enforcement', 'Police Operations', 'What is predictive policing?', '["Using algorithms to forecast crime", "Random patrols", "Historical review", "No analysis"]'::jsonb, 0, 'hard', 'Predictive policing uses data algorithms to anticipate where crimes may occur.'),
('lea_133', 'law_enforcement', 'Police Psychology', 'What is police stress syndrome?', '["Cumulative stress affecting officers", "Normal job satisfaction", "Promotion happiness", "Career advancement"]'::jsonb, 0, 'hard', 'Police stress syndrome is the cumulative psychological impact of police work.'),
('lea_134', 'law_enforcement', 'Police Organization', 'What is decentralization in policing?', '["Distributing authority to local units", "Central control only", "No structure", "Single command"]'::jsonb, 0, 'hard', 'Decentralization distributes decision-making authority to lower organizational levels.'),
('lea_135', 'law_enforcement', 'Police Ethics', 'What is noble cause corruption?', '["Breaking rules for good ends", "Taking bribes", "Theft", "Violence"]'::jsonb, 0, 'hard', 'Noble cause corruption is violating rules to achieve perceived justice.'),
('lea_136', 'law_enforcement', 'Police Planning', 'What is tactical planning?', '["Short-term operational planning", "Long-term strategy", "No planning", "Budget only"]'::jsonb, 0, 'hard', 'Tactical planning focuses on short-term actions to achieve specific objectives.'),
('lea_137', 'law_enforcement', 'Police Administration', 'What is span of management?', '["Number of subordinates one can supervise", "Budget range", "Time period", "Geographic area"]'::jsonb, 0, 'hard', 'Span of management refers to how many subordinates a supervisor can effectively manage.'),
('lea_138', 'law_enforcement', 'Police Operations', 'What is problem-oriented policing?', '["Addressing underlying causes of crime", "Random responses", "Reactive only", "No analysis"]'::jsonb, 0, 'hard', 'Problem-oriented policing identifies and addresses root causes of crime problems.'),
('lea_139', 'law_enforcement', 'Police Ethics', 'What is procedural justice?', '["Fair and transparent police processes", "Harsh punishment", "Quick trials", "No procedures"]'::jsonb, 0, 'hard', 'Procedural justice emphasizes fair, transparent processes in police encounters.'),
('lea_140', 'law_enforcement', 'Police Administration', 'What is evidence-based policing?', '["Using research to guide practices", "Intuition only", "Tradition only", "No research"]'::jsonb, 0, 'hard', 'Evidence-based policing uses scientific research to inform police strategies.'),
('lea_141', 'law_enforcement', 'Police Organization', 'What is organizational culture in policing?', '["Shared values and norms in agency", "Physical building", "Equipment", "Budget"]'::jsonb, 0, 'hard', 'Organizational culture encompasses the shared values and beliefs within a police agency.'),
('lea_142', 'law_enforcement', 'Police Operations', 'What is COMPSTAT?', '["Computer statistics for crime analysis", "Computer system type", "Communication device", "Training program"]'::jsonb, 0, 'hard', 'COMPSTAT is a management system using computer statistics to analyze crime patterns.')
